const TEXTS = [{"topic": "Gezondheid", "title": "Bewegen is goed voor je, maar hoeveel is genoeg?", "paragraphs": ["Veel mensen weten dat bewegen gezond is, maar ze vragen zich af hoeveel beweging ze eigenlijk nodig hebben. Volgens de Nederlandse gezondheidsnormen is het aanbevolen om elke week minstens 150 minuten matig intensief te bewegen. Dat betekent iets doen waarbij je hartslag stijgt en je licht buiten adem raakt, zoals stevig wandelen of fietsen.", "Toch halen veel Nederlanders deze norm niet. Uit onderzoek blijkt dat ruim de helft van de bevolking te weinig beweegt. Mensen zeggen vaak dat ze geen tijd hebben, maar ook een korte wandeling van tien minuten telt mee. Bovendien is het bewezen dat regelmatig bewegen stress vermindert en de slaap verbetert.", "Sporten in een sportschool is niet de enige manier om actief te zijn. Trap lopen in plaats van de lift nemen, de fiets pakken naar het werk, of in de tuin werken zijn ook goede manieren om meer te bewegen. Het gaat erom dat je minder lang stilzit en vaker je lichaam gebruikt.", "Mensen die op latere leeftijd beginnen met bewegen, merken al snel verbeteringen in hun gezondheid. Het is dus nooit te laat om te starten. Zelfs kleine veranderingen in je dagelijkse routine kunnen een groot verschil maken voor je gezondheid op de lange termijn."], "questions": [{"text": "Hoeveel minuten per week moeten Nederlanders minimaal bewegen?", "type": "Detail", "options": ["100 minuten", "150 minuten", "200 minuten", "250 minuten"], "correct": 1, "highlight": "minstens 150 minuten matig intensief te bewegen", "feedback": {"ok": "Goed! De norm is 150 minuten per week.", "nee": "Niet juist. Alinea 1 noemt 150 minuten als aanbevolen norm."}}, {"text": "Waarom bewegen veel Nederlanders te weinig?", "type": "Detail", "options": ["Ze vinden bewegen saai.", "Ze zeggen dat ze geen tijd hebben.", "Ze wonen te ver van een sportschool.", "Ze zijn bang voor blessures."], "correct": 1, "highlight": "Mensen zeggen vaak dat ze geen tijd hebben", "feedback": {"ok": "Correct! Mensen zeggen dat ze geen tijd hebben.", "nee": "Niet correct. Alinea 2 zegt dat mensen zeggen geen tijd te hebben."}}, {"text": "Wat suggereert de tekst als alternatief voor de sportschool?", "type": "Inferentie", "options": ["Elke dag zwemmen.", "Altijd de auto nemen.", "Trap lopen in plaats van de lift.", "Een personal trainer inhuren."], "correct": 2, "highlight": "Trap lopen in plaats van de lift nemen", "feedback": {"ok": "Goed! Alinea 3 noemt de trap als voorbeeld.", "nee": "Niet juist. Zie alinea 3: trap lopen, fietsen, tuinieren."}}, {"text": "Wat betekent 'matig intensief bewegen'?", "type": "Woordbetekenis", "options": ["Heel zwaar sporten.", "Rustig wandelen zonder inspanning.", "Je hartslag stijgt en je raakt licht buiten adem.", "Zwemmen in een wedstrijd."], "correct": 2, "highlight": "je hartslag stijgt en je licht buiten adem raakt", "feedback": {"ok": "Juist! Matig intensief = hartslag omhoog, licht buiten adem.", "nee": "Niet juist. Alinea 1 legt 'matig intensief' zo uit."}}, {"text": "Wat is de hoofdboodschap van deze tekst?", "type": "Hoofdgedachte", "options": ["Ga elke dag naar de sportschool.", "Bewegen helpt alleen jonge mensen.", "Kleine veranderingen kunnen al een groot verschil maken.", "Alleen intensief sporten telt mee."], "correct": 2, "highlight": "Zelfs kleine veranderingen in je dagelijkse routine kunnen een groot verschil maken", "feedback": {"ok": "Prima! Kleine veranderingen maken al een groot verschil.", "nee": "Niet helemaal. De kern is dat kleine veranderingen al een groot verschil kunnen maken."}}]}, {"topic": "Wonen", "title": "Tiny houses: klein wonen als grote trend", "paragraphs": ["In Nederland groeit de interesse in tiny houses. Dit zijn kleine, compacte woningen van meestal tussen de vijftien en vijftig vierkante meter. Ze zijn populair bij mensen die bewust minder willen consumeren, goedkoper willen wonen, of dicht bij de natuur willen leven.", "Een tiny house kopen is goedkoper dan een gewone woning, maar het vinden van een geschikte plek is vaak moeilijk. Niet alle gemeenten staan toe dat je een tiny house op een perceel plaatst. Er zijn speciale tiny house parken in opkomst, maar die hebben lange wachtlijsten.", "Leven in een tiny house vraagt om aanpassing. Je hebt minder ruimte voor spullen, dus je moet goed nadenken over wat je echt nodig hebt. Veel bewoners zeggen dat ze na een tijdje merken dat ze zich vrijer voelen omdat ze minder bezittingen hebben.", "Critici wijzen erop dat tiny houses niet voor iedereen geschikt zijn. Gezinnen met kinderen hebben meer ruimte nodig, en in de winter kan een kleine ruimte snel koud aanvoelen. Toch zien steeds meer mensen het als een aantrekkelijke manier om de woonlasten te verlagen en duurzamer te leven."], "questions": [{"text": "Hoe groot is een tiny house meestal?", "type": "Detail", "options": ["5-15 m²", "Meer dan 100 m²", "15-50 m²", "50-80 m²"], "correct": 2, "highlight": "tussen de vijftien en vijftig vierkante meter", "feedback": {"ok": "Goed! Tussen 15 en 50 m².", "nee": "Niet juist. Alinea 1: tussen 15 en 50 vierkante meter."}}, {"text": "Wat is een van de grootste problemen bij het kopen van een tiny house?", "type": "Detail", "options": ["Ze zijn te duur.", "De bouw duurt erg lang.", "Er zijn te weinig modellen.", "Het is moeilijk een geschikte plek te vinden."], "correct": 3, "highlight": "het vinden van een geschikte plek is vaak moeilijk", "feedback": {"ok": "Correct! Een geschikte locatie vinden is het probleem.", "nee": "Niet correct. Alinea 2 noemt het vinden van een plek als groot probleem."}}, {"text": "Wat zeggen veel bewoners over hun ervaring?", "type": "Detail", "options": ["Ze missen hun oude huis.", "Ze willen snel weer verhuizen.", "Ze voelen zich vrijer door minder bezittingen.", "Ze vinden de ruimte te koud."], "correct": 2, "highlight": "ze zich vrijer voelen omdat ze minder bezittingen hebben", "feedback": {"ok": "Juist! Bewoners voelen zich vrijer met minder bezittingen.", "nee": "Niet juist. Alinea 3: bewoners voelen zich vrijer."}}, {"text": "Wat betekent 'woonlasten' (alinea 4)?", "type": "Woordbetekenis", "options": ["De grootte van je huis", "De afstand tot je werk", "De kwaliteit van je buurt", "De kosten van je woning"], "correct": 3, "highlight": "woonlasten te verlagen en duurzamer te leven", "feedback": {"ok": "Goed! Woonlasten = kosten voor je woning.", "nee": "Niet juist. 'Woonlasten' zijn de kosten die je voor je woning betaalt."}}, {"text": "Welke groep vindt tiny houses minder geschikt?", "type": "Inferentie", "options": ["Mensen die dicht bij natuur willen wonen", "Bewuste consumenten", "Gezinnen met kinderen", "Mensen die goedkoper willen wonen"], "correct": 2, "highlight": "Gezinnen met kinderen hebben meer ruimte nodig", "feedback": {"ok": "Correct! Gezinnen met kinderen hebben meer ruimte nodig.", "nee": "Niet correct. Alinea 4 noemt gezinnen met kinderen."}}]}, {"topic": "Werk", "title": "Thuiswerken: voordeel of nadeel?", "paragraphs": ["Tijdens de coronapandemie moesten veel mensen thuis gaan werken. Sindsdien is thuiswerken in Nederland heel gewoon geworden. Veel bedrijven bieden nu een hybride werkmodel aan, waarbij werknemers een deel van de week thuis werken en een deel op kantoor.", "Thuiswerken heeft duidelijke voordelen. Je bespaart reistijd en reiskosten, en je kunt je werkdag flexibeler indelen. Veel mensen geven aan dat ze thuis beter kunnen concentreren omdat er minder afleidingen zijn dan op kantoor.", "Maar thuiswerken kent ook nadelen. Sommige mensen missen het sociale contact met collega's. De grens tussen werk en privé kan vervagen, waardoor mensen moeilijker kunnen stoppen met werken. Daarnaast heeft niet iedereen thuis een fijne werkplek met een goede stoel en voldoende licht.", "Bedrijven merken dat het hybride model populair is, maar ze vinden het soms moeilijk om de samenwerking tussen collega's goed te houden. Er wordt steeds meer nagedacht over hoe kantoren ingericht moeten worden om samenwerken te bevorderen op de dagen dat mensen wel op kantoor komen."], "questions": [{"text": "Wat is een hybride werkmodel?", "type": "Woordbetekenis", "options": ["Altijd thuis werken", "Werken in het buitenland", "Altijd op kantoor werken", "Deels thuis en deels op kantoor werken"], "correct": 3, "highlight": "werknemers een deel van de week thuis werken en een deel op kantoor", "feedback": {"ok": "Goed! Hybride = deels thuis, deels op kantoor.", "nee": "Niet juist. Alinea 1: deels thuis én deels op kantoor."}}, {"text": "Waarom kunnen mensen thuis beter concentreren?", "type": "Detail", "options": ["Ze beginnen thuis eerder.", "Ze hebben een betere computer thuis.", "Er zijn thuis minder afleidingen dan op kantoor.", "Ze hebben meer collega's om te helpen."], "correct": 2, "highlight": "ze thuis beter kunnen concentreren omdat er minder afleidingen zijn", "feedback": {"ok": "Correct! Minder afleidingen thuis.", "nee": "Niet correct. Alinea 2: minder afleidingen dan op kantoor."}}, {"text": "Wat is een nadeel van thuiswerken?", "type": "Detail", "options": ["Je verdient minder.", "Je moet elke dag reizen.", "Je hebt geen toegang tot software.", "Je mist contact met collega's."], "correct": 3, "highlight": "Sommige mensen missen het sociale contact met collegaâs", "feedback": {"ok": "Goed! Missen van sociaal contact is een nadeel.", "nee": "Niet juist. Alinea 3 noemt het missen van contact met collega's."}}, {"text": "Wat betekent 'de grens tussen werk en privé kan vervagen'?", "type": "Woordbetekenis", "options": ["Je werkt op meerdere plekken.", "Je collega's weten niet waar je woont.", "Je privéleven wordt gecontroleerd.", "Het wordt moeilijk te scheiden wanneer je werkt en wanneer niet."], "correct": 3, "highlight": "De grens tussen werk en privé kan vervagen, waardoor mensen moeilijker kunnen stoppen met werken", "feedback": {"ok": "Juist! Vervagen = het onderscheid wordt onduidelijk.", "nee": "Niet juist. Vervagen betekent dat het onderscheid wazig wordt."}}, {"text": "Waarom denken bedrijven na over kantoorinrichting?", "type": "Inferentie", "options": ["Omdat huurprijzen te hoog zijn.", "Kantoren zijn te groot geworden.", "Om meer mensen thuis te laten werken.", "Om samenwerken te bevorderen op kantoordagen."], "correct": 3, "highlight": "hoe kantoren ingericht moeten worden om samenwerken te bevorderen", "feedback": {"ok": "Prima! Kantoren worden ingericht voor betere samenwerking.", "nee": "Niet correct. Alinea 4: kantoren worden heringericht voor samenwerking."}}]}, {"topic": "Natuur", "title": "Het Nederlandse landschap: van veen tot delta", "paragraphs": ["Nederland is een van de laagstgelegen landen ter wereld. Grote delen van het land liggen onder zeeniveau. Dit is mogelijk dankzij een uitgebreid systeem van dijken, gemalen en sluizen dat het water op afstand houdt. Zonder dit systeem zou een groot deel van het westen en noorden van het land regelmatig overstromen.", "Het landschap van Nederland is door eeuwen van menselijk ingrijpen sterk veranderd. Vroeger bestond een groot deel van het land uit moeras en veen. Door het droogleggen van polders en het afgraven van veen ontstonden de vlakke, open weilanden die nu zo kenmerkend zijn voor het Nederlandse landschap.", "De rivieren Rijn, Maas en Waal spelen een belangrijke rol in het landschap. Ze voeren water af vanuit het bergachtige binnenland van Europa naar de Noordzee. In de delta waar ze in zee uitstromen, hebben ze een rijke natuur gecreëerd met rietlanden, zandbanken en getijdengebieden.", "Het Nederlandse landschap staat vandaag de dag onder druk door klimaatverandering. De zeespiegel stijgt en extreme regenval komt vaker voor. De overheid en waterschappen werken samen om het land ook in de toekomst droog en veilig te houden, maar dit vraagt om steeds grotere investeringen."], "questions": [{"text": "Waardoor is het mogelijk dat grote delen van Nederland onder zeeniveau liggen?", "type": "Detail", "options": ["Het land ligt op een hoog plateau.", "Dankzij speciale bouwmaterialen.", "De zee is in Nederland minder hoog.", "Dankzij dijken, gemalen en sluizen."], "correct": 3, "highlight": "een uitgebreid systeem van dijken, gemalen en sluizen dat het water op afstand houdt", "feedback": {"ok": "Goed! Dijken, gemalen en sluizen houden het water op afstand.", "nee": "Niet juist. Alinea 1: het systeem van dijken, gemalen en sluizen."}}, {"text": "Hoe zag het Nederlandse landschap er vroeger uit?", "type": "Detail", "options": ["Een uitgestrekt strand.", "Bergachtig met bossen.", "Een droge, zandige vlakte.", "Een groot moeras- en veengebied."], "correct": 3, "highlight": "Vroeger bestond een groot deel van het land uit moeras en veen", "feedback": {"ok": "Correct! Vroeger bestond het land grotendeels uit moeras en veen.", "nee": "Niet correct. Alinea 2: vroeger moeras en veen."}}, {"text": "Waar stromen de Rijn, Maas en Waal naartoe?", "type": "Detail", "options": ["Middellandse Zee.", "IJsselmeer.", "Atlantische Oceaan.", "Noordzee."], "correct": 3, "highlight": "Ze voeren water af vanuit het bergachtige binnenland van Europa naar de Noordzee", "feedback": {"ok": "Juist! De rivieren stromen naar de Noordzee.", "nee": "Niet juist. Alinea 3: de rivieren voeren water af naar de Noordzee."}}, {"text": "Wat betekent 'getijdengebied' (alinea 3)?", "type": "Woordbetekenis", "options": ["Een gebied met veel bomen.", "Een gebied waar rivieren samenkomen.", "Een gebied met alleen zandduinen.", "Een gebied dat afwisselend droogvalt en onderloopt door het getij."], "correct": 3, "highlight": "rietlanden, zandbanken en getijdengebieden", "feedback": {"ok": "Goed! Een getijdengebied staat onder invloed van eb en vloed.", "nee": "Niet juist. Een getijdengebied wordt bepaald door eb en vloed."}}, {"text": "Welke uitdaging noemt de tekst voor de toekomst?", "type": "Hoofdgedachte", "options": ["Te veel mensen in het westen.", "Tekort aan rivierwater.", "Te weinig natuur door landbouw.", "Klimaatverandering en stijgende zeespiegel."], "correct": 3, "highlight": "De zeespiegel stijgt en extreme regenval komt vaker voor", "feedback": {"ok": "Prima! Klimaatverandering en stijgende zeespiegel zijn de grote uitdagingen.", "nee": "Niet correct. Alinea 4: klimaatverandering en stijgende zeespiegel."}}]}, {"topic": "Onderwijs", "title": "Leren met je telefoon: kans of afleiding?", "paragraphs": ["Smartphones zijn niet meer weg te denken uit het dagelijks leven van jongeren. Steeds meer scholen experimenteren met apps en digitale hulpmiddelen in de les. Voorstanders zeggen dat technologie het leren interessanter en persoonlijker kan maken. Leerlingen kunnen in hun eigen tempo werken en direct feedback krijgen.", "Tegelijkertijd zijn er zorgen over de keerzijde van smartphones in de klas. Onderzoek toont aan dat leerlingen die hun telefoon naast zich hebben liggen, moeilijker kunnen focussen — zelfs als de telefoon uitstaat. De verleiding om te scrollen of berichten te checken is voor veel jongeren te groot.", "Sommige scholen hebben daarom gekozen voor een telefoonverbod. Leerlingen moeten hun telefoon bij binnenkomst inleveren in een kluisje. Voorstanders van dit beleid melden betere concentratie en meer sociale interactie op het schoolplein. Tegenstanders vinden dat jongeren moeten leren omgaan met digitale verleidingen.", "Het debat over telefoons op school is niet snel opgelost. Veel hangt af van de manier waarop een school technologie inzet. Wordt de telefoon ingezet als leermiddel met duidelijke regels, of is het een vrij beschikbaar apparaat zonder begeleiding? Het antwoord bepaalt grotendeels of technologie helpt of schaadt in het onderwijs."], "questions": [{"text": "Wat zeggen voorstanders over smartphones in de les?", "type": "Detail", "options": ["Ze zijn goedkoper dan boeken.", "Ze vervangen de leraar volledig.", "Ze zijn noodzakelijk voor huiswerk.", "Ze maken leren interessanter en persoonlijker."], "correct": 3, "highlight": "technologie het leren interessanter en persoonlijker kan maken", "feedback": {"ok": "Goed! Interessanter en persoonlijker leren.", "nee": "Niet juist. Alinea 1: technologie maakt leren interessanter en persoonlijker."}}, {"text": "Wat toont onderzoek aan over telefoons naast leerlingen?", "type": "Detail", "options": ["Oudere leerlingen worden niet gestoord.", "Leerlingen leren sneller.", "Leerlingen focussen moeilijker, zelfs als de telefoon uitstaat.", "Telefoons storen alleen als ze aanstaan."], "correct": 2, "highlight": "leerlingen die hun telefoon naast zich hebben liggen, moeilijker kunnen focussen", "feedback": {"ok": "Correct! Zelfs een uitgestaande telefoon naast je vermindert focus.", "nee": "Niet correct. Alinea 2: zelfs een uitgestaande telefoon is al storend."}}, {"text": "Wat is een argument tegen een telefoonverbod?", "type": "Inferentie", "options": ["Leraren weten niet hoe ze apps moeten gebruiken.", "Telefoons zijn te duur om in kluisjes te bewaren.", "Jongeren moeten leren omgaan met digitale verleidingen.", "Telefoons zijn nodig voor noodgevallen."], "correct": 2, "highlight": "Tegenstanders vinden dat jongeren moeten leren omgaan met digitale verleidingen", "feedback": {"ok": "Juist! Jongeren moeten digitale verleidingen leren weerstaan.", "nee": "Niet juist. Alinea 3: tegenstanders vinden dat jongeren dit moeten leren."}}, {"text": "Wat betekent 'leermiddel' (alinea 4)?", "type": "Woordbetekenis", "options": ["Een systeem om leerlingen te controleren", "Een website voor leraren", "Een apparaat om games te spelen", "Een hulpmiddel om iets te leren"], "correct": 3, "highlight": "Wordt de telefoon ingezet als leermiddel met duidelijke regels", "feedback": {"ok": "Goed! Een leermiddel is een hulpmiddel bij het leren.", "nee": "Niet juist. Een leermiddel is iets wat je helpt bij het leren."}}, {"text": "Wat bepaalt of technologie helpt in het onderwijs?", "type": "Hoofdgedachte", "options": ["Het merk van de telefoon.", "Het aantal lessen per dag.", "De leeftijd van de leerlingen.", "De manier waarop een school technologie inzet."], "correct": 3, "highlight": "Veel hangt af van de manier waarop een school technologie inzet", "feedback": {"ok": "Prima! De manier van inzet bepaalt het effect.", "nee": "Niet correct. Alinea 4: het hangt af van hoe de school technologie inzet."}}]}, {"topic": "Vervoer", "title": "De trein in Nederland: populair maar vol", "paragraphs": ["De NS, de Nederlandse Spoorwegen, vervoert elke dag ruim een miljoen reizigers. Het treinnetwerk verbindt vrijwel alle grote steden en veel kleinere plaatsen met elkaar. Voor veel mensen is de trein de snelste en gemakkelijkste manier om van A naar B te reizen, zeker tijdens de spits.", "Toch kampt het treinverkeer in Nederland met problemen. Treinen rijden regelmatig te laat door storingen, werkzaamheden aan het spoor of problemen met de bovenleidingen. Reizigers klagen al jaren over overvolle coupés en onbetrouwbare verbindingen, vooral op drukke trajecten zoals Amsterdam-Utrecht.", "De NS en de overheid werken aan verbeteringen. Er worden nieuwe treinen aangeschaft die meer capaciteit bieden. Ook wordt er geïnvesteerd in het verdubbelen van spoorlijnen, zodat er meer treinen kunnen rijden op populaire routes. Maar dit soort grote projecten kost jaren en veel geld.", "Een alternatief dat steeds populairder wordt, is de combinatie van fiets en trein. Reizigers pakken de fiets naar het station en stappen dan in de trein. Op veel stations zijn grote fietsenstallingen gebouwd om hieraan tegemoet te komen. Deze combinatie wordt gezien als een duurzame oplossing voor de drukte op de wegen en in de treinen."], "questions": [{"text": "Hoeveel reizigers vervoert de NS per dag?", "type": "Detail", "options": ["Meer dan twee miljoen", "Ruim honderdduizend", "Ruim een half miljoen", "Ruim een miljoen"], "correct": 3, "highlight": "vervoert elke dag ruim een miljoen reizigers", "feedback": {"ok": "Goed! Ruim een miljoen reizigers per dag.", "nee": "Niet juist. Alinea 1: ruim een miljoen reizigers per dag."}}, {"text": "Wat is een veelgenoemde klacht van treinreizigers?", "type": "Detail", "options": ["Er zijn te weinig stations.", "Treinen zijn te duur.", "De treinen zijn te oud.", "Overvolle coupés en onbetrouwbare verbindingen."], "correct": 3, "highlight": "Reizigers klagen al jaren over overvolle coupés en onbetrouwbare verbindingen", "feedback": {"ok": "Correct! Overvolle coupés en onbetrouwbare verbindingen.", "nee": "Niet correct. Alinea 2: overvolle coupés en onbetrouwbare verbindingen."}}, {"text": "Wat is een oplossing die de NS en overheid nemen?", "type": "Detail", "options": ["Treinprijzen verlagen.", "Minder treinen laten rijden.", "Het treinnet inkrimpen.", "Nieuwe treinen aanschaffen met meer capaciteit."], "correct": 3, "highlight": "Er worden nieuwe treinen aangeschaft die meer capaciteit bieden", "feedback": {"ok": "Juist! Nieuwe treinen met meer capaciteit.", "nee": "Niet juist. Alinea 3: nieuwe treinen aanschaffen die meer capaciteit bieden."}}, {"text": "Wat betekent 'capaciteit' (alinea 3)?", "type": "Woordbetekenis", "options": ["De staat van het spoor", "De snelheid van een trein", "De prijs van een treinkaartje", "Het aantal mensen of dingen dat iets kan bevatten"], "correct": 3, "highlight": "nieuwe treinen aangeschaft die meer capaciteit bieden", "feedback": {"ok": "Goed! Capaciteit = hoeveel iets kan bevatten of vervoeren.", "nee": "Niet juist. Capaciteit verwijst naar het aantal mensen dat iets kan vervoeren."}}, {"text": "Waarom wordt de combinatie fiets en trein als duurzame oplossing gezien?", "type": "Inferentie", "options": ["Fietsenstallingen zijn goedkoop te bouwen.", "Het is goedkoper dan alleen de trein.", "Fietsen is sneller dan treinrijden.", "Het vermindert de drukte op wegen en in treinen."], "correct": 3, "highlight": "Deze combinatie wordt gezien als een duurzame oplossing voor de drukte op de wegen en in de treinen", "feedback": {"ok": "Prima! Minder drukte op wegen én in treinen.", "nee": "Niet correct. Alinea 4: de combinatie vermindert drukte op wegen en in treinen."}}]}, {"topic": "Milieu", "title": "Plastic soep: het probleem in onze oceanen", "paragraphs": ["Elk jaar belandt er miljoenen ton plastic afval in de oceanen. Dit plastic breekt niet af, maar valt uiteen in steeds kleinere deeltjes, zogenaamde microplastics. Vissen en andere zeedieren eten deze deeltjes, waardoor ze in de voedselketen terechtkomen — en uiteindelijk ook op ons bord.", "De term 'plastic soep' werd populair nadat onderzoekers grote concentraties plastic ontdekten in de Stille Oceaan. Het plastic komt uit rivieren, van stranden en uit het riool. Vooral wegwerpplastic zoals flesjes, rietjes en tasjes zijn grote boosdoeners.", "Overheden en organisaties proberen het probleem aan te pakken. De Europese Unie heeft wegwerpplastic zoals plastic rietjes en roerstaafjes verboden. Supermarkten vragen een vergoeding voor plastic tassen om het gebruik te verminderen. Maar experts zeggen dat deze maatregelen niet genoeg zijn.", "Consumenten kunnen ook zelf bijdragen. Minder plastic gebruiken, afval goed scheiden en kiezen voor herbruikbare producten zijn kleine stappen die samen een groot verschil kunnen maken. Maar een echte oplossing vraagt om samenwerking tussen bedrijven, overheden en burgers wereldwijd."], "questions": [{"text": "Wat zijn microplastics?", "type": "Woordbetekenis", "options": ["Een soort kunststof voor verpakkingen", "Grote stukken plastic in zee", "Plastic tasjes in winkels", "Zeer kleine plastic deeltjes"], "correct": 3, "highlight": "valt uiteen in steeds kleinere deeltjes, zogenaamde microplastics", "feedback": {"ok": "Goed! Microplastics zijn zeer kleine plastic deeltjes.", "nee": "Niet juist. Alinea 1: microplastics zijn kleine deeltjes die ontstaan als plastic uiteenvalt."}}, {"text": "Waar komt het plastic in de oceanen vandaan?", "type": "Detail", "options": ["Alleen van schepen.", "Van onderwaterpijplijnen.", "Alleen van de visindustrie.", "Uit rivieren, stranden en het riool."], "correct": 3, "highlight": "Het plastic komt uit rivieren, van stranden en uit het riool", "feedback": {"ok": "Correct! Rivieren, stranden en riool.", "nee": "Niet correct. Alinea 2: rivieren, stranden en riool."}}, {"text": "Welke maatregel heeft de EU genomen?", "type": "Detail", "options": ["Plastic auto-onderdelen verboden.", "Alle plastic verpakkingen verboden.", "Plastic speelgoed verboden.", "Wegwerpplastic zoals rietjes en roerstaafjes verboden."], "correct": 3, "highlight": "De Europese Unie heeft wegwerpplastic zoals plastic rietjes en roerstaafjes verboden", "feedback": {"ok": "Juist! Plastic rietjes en roerstaafjes zijn verboden door de EU.", "nee": "Niet juist. Alinea 3: de EU verbood plastic rietjes en roerstaafjes."}}, {"text": "Wat kunnen consumenten zelf doen?", "type": "Inferentie", "options": ["Naar de overheid schrijven.", "Alleen biologisch voedsel kopen.", "Plastic afval in zee gooien.", "Minder plastic gebruiken en kiezen voor herbruikbare producten."], "correct": 3, "highlight": "Minder plastic gebruiken, afval goed scheiden en kiezen voor herbruikbare producten", "feedback": {"ok": "Goed! Minder plastic en herbruikbare producten.", "nee": "Niet juist. Alinea 4: minder plastic, goed scheiden en herbruikbare producten."}}, {"text": "Wat is de hoofdboodschap van de tekst?", "type": "Hoofdgedachte", "options": ["Plastic in oceanen is al volledig opgelost.", "Microplastics zijn onschadelijk voor mensen.", "Alleen overheden kunnen plastic soep oplossen.", "Het plastic probleem vraagt om samenwerking en actie van consumenten."], "correct": 3, "highlight": "een echte oplossing vraagt om samenwerking tussen bedrijven, overheden en burgers wereldwijd", "feedback": {"ok": "Prima! Samenwerking op alle niveaus is nodig.", "nee": "Niet helemaal. De tekst benadrukt dat samenwerking op alle niveaus nodig is."}}]}, {"topic": "Taal & cultuur", "title": "Nederlands leren als volwassene: uitdaging en kans", "paragraphs": ["Elk jaar beginnen tienduizenden mensen in Nederland aan een cursus Nederlands als tweede taal, ook wel NT2 genoemd. Het gaat om nieuwkomers, expats en mensen die al jaren in Nederland wonen maar de taal nog niet goed spreken. De motivaties zijn divers: werk vinden, beter communiceren met buren, of inburgeren.", "Nederlands wordt door veel leerders als een moeilijke taal beschouwd. De uitspraak is lastig, met klanken die in andere talen niet voorkomen, zoals de 'g' en de 'ui'. Ook de grammatica, met de twee lidwoorden 'de' en 'het', geeft veel mensen hoofdbrekens. Toch zeggen veel cursisten dat ze snel vooruitgang merken als ze de taal ook buiten de les oefenen.", "Taalscholen, gemeenten en bibliotheken bieden NT2-cursussen aan op verschillende niveaus. Het staatsexamen NT2 is een officieel examen dat bestaat uit vier onderdelen: lezen, luisteren, schrijven en spreken. Dit examen is verplicht voor mensen die willen inburgeren of een permanente verblijfsvergunning willen aanvragen.", "Experts adviseren om zoveel mogelijk Nederlands te spreken in het dagelijks leven. Televisie kijken met Nederlandse ondertiteling, Nederlandse kranten lezen of vrijwilligerswerk doen zijn goede manieren om de taal te oefenen. De sleutel is: niet bang zijn om fouten te maken, want van fouten leer je het meest."], "questions": [{"text": "Wie volgen NT2-cursussen?", "type": "Detail", "options": ["Alleen studenten aan Nederlandse universiteiten.", "Alleen nieuwkomers uit vluchtelingenkampen.", "Alleen mensen met een werkvergunning.", "Nieuwkomers, expats en mensen die al jaren in Nederland wonen."], "correct": 3, "highlight": "nieuwkomers, expats en mensen die al jaren in Nederland wonen maar de taal nog niet goed spreken", "feedback": {"ok": "Goed! Nieuwkomers, expats én langdurige inwoners.", "nee": "Niet juist. Alinea 1: nieuwkomers, expats en mensen die al jaren in Nederland wonen."}}, {"text": "Wat vinden veel leerders moeilijk aan het Nederlands?", "type": "Detail", "options": ["Het schrijven van brieven.", "De uitspraak en de twee lidwoorden 'de' en 'het'.", "Het leren van cijfers en getallen.", "De lange zinnen in kranten."], "correct": 1, "highlight": "De uitspraak is lastig", "feedback": {"ok": "Correct! Uitspraak en de lidwoorden zijn bekende struikelblokken.", "nee": "Niet correct. Alinea 2: de uitspraak en de lidwoorden 'de' en 'het' zijn moeilijk."}}, {"text": "Waarvoor is het staatsexamen NT2 verplicht?", "type": "Detail", "options": ["Voor werk bij de Nederlandse overheid.", "Voor toegang tot universiteiten.", "Voor alle nieuwe inwoners direct bij aankomst.", "Voor inburgering of een permanente verblijfsvergunning."], "correct": 3, "highlight": "verplicht voor mensen die willen inburgeren of een permanente verblijfsvergunning willen aanvragen", "feedback": {"ok": "Juist! Voor inburgering of een permanente verblijfsvergunning.", "nee": "Niet juist. Alinea 3: verplicht voor inburgering of een permanente verblijfsvergunning."}}, {"text": "Wat adviseren experts om de taal te verbeteren?", "type": "Inferentie", "options": ["Alleen schriftelijk oefenen.", "Pas spreken als je perfect bent.", "Alleen naar taalschool gaan.", "Zoveel mogelijk Nederlands spreken in het dagelijks leven."], "correct": 3, "highlight": "zoveel mogelijk Nederlands te spreken in het dagelijks leven", "feedback": {"ok": "Goed! Oefenen in het dagelijks leven is het advies.", "nee": "Niet juist. Alinea 4: experts adviseren zoveel mogelijk Nederlands te spreken."}}, {"text": "Wat is de sleutel tot succes bij het leren van Nederlands?", "type": "Hoofdgedachte", "options": ["Een taalapp gebruiken.", "Heel veel geld investeren in cursussen.", "Alleen met Nederlanders omgaan.", "Niet bang zijn om fouten te maken."], "correct": 3, "highlight": "niet bang zijn om fouten te maken, want van fouten leer je het meest", "feedback": {"ok": "Prima! Niet bang zijn voor fouten — daar leer je van.", "nee": "Niet correct. Alinea 4: de sleutel is niet bang zijn om fouten te maken."}}]}, {"topic": "Duurzaamheid", "title": "Zonnepanelen in Nederland: een zonnige toekomst?", "paragraphs": ["Nederland telt inmiddels meer dan drie miljoen huishoudens met zonnepanelen op het dak. Dat is een enorme groei vergeleken met tien jaar geleden, toen zonnepanelen nog schaars en erg duur waren. De dalende kosten en subsidies van de overheid hebben de populariteit sterk vergroot.", "Zonnepanelen produceren elektriciteit uit zonlicht. In Nederland schijnt de zon minder dan in landen als Spanje of Italië, maar er is genoeg zonlicht om zonnepanelen rendabel te maken. Op een zonnige dag kan een gemiddeld huishouden meer stroom opwekken dan het zelf gebruikt, en het overschot kan worden teruggeleverd aan het elektriciteitsnet.", "Niet iedereen kan echter zonnepanelen plaatsen. Mensen die in een huurhuis of appartement wonen, zijn afhankelijk van de beslissing van hun verhuurder of vereniging van eigenaars. Bovendien zijn niet alle daken geschikt vanwege de richting of schaduw van bomen en andere gebouwen.", "De Nederlandse overheid stimuleert de overgang naar hernieuwbare energie, maar er zijn ook zorgen. Het elektriciteitsnet is op sommige plekken overbelast doordat er te veel stroom tegelijk wordt ingevoed. Netbeheerders werken aan uitbreidingen, maar dat kost tijd en geld."], "questions": [{"text": "Waardoor zijn zonnepanelen populairder geworden?", "type": "Detail", "options": ["Buurlanden begonnen er ook mee.", "De zon schijnt meer dan vroeger.", "Huurhuizen zijn verplicht panelen te plaatsen.", "Dalende kosten en overheidssubsidies."], "correct": 3, "highlight": "De dalende kosten en subsidies van de overheid hebben de populariteit sterk vergroot", "feedback": {"ok": "Goed! Dalende kosten en subsidies zijn de reden.", "nee": "Niet juist. Alinea 1: dalende kosten en overheidssubsidies."}}, {"text": "Wat gebeurt er als een huishouden meer stroom opwekt dan het gebruikt?", "type": "Detail", "options": ["De stroom gaat verloren.", "De panelen stoppen automatisch.", "Het overschot wordt in een batterij opgeslagen.", "Het overschot wordt teruggeleverd aan het net."], "correct": 3, "highlight": "het overschot kan worden teruggeleverd aan het elektriciteitsnet", "feedback": {"ok": "Correct! Het overschot gaat terug naar het net.", "nee": "Niet correct. Alinea 2: terugleveren aan het elektriciteitsnet."}}, {"text": "Waarom kunnen niet alle mensen zonnepanelen plaatsen?", "type": "Inferentie", "options": ["De montage duurt te lang.", "De overheid staat het niet toe.", "Ze zijn nog te duur.", "Huurders zijn afhankelijk van hun verhuurder."], "correct": 3, "highlight": "zijn afhankelijk van de beslissing van hun verhuurder of vereniging van eigenaars", "feedback": {"ok": "Juist! Huurders hebben toestemming nodig van de verhuurder.", "nee": "Niet juist. Alinea 3: huurders zijn afhankelijk van hun verhuurder."}}, {"text": "Wat betekent 'hernieuwbare energie' (alinea 4)?", "type": "Woordbetekenis", "options": ["Energie die duurder is", "Energie die 's nachts beschikbaar is", "Energie uit gas", "Energie die niet opraakt, zoals zon en wind"], "correct": 3, "highlight": "de overgang naar hernieuwbare energie", "feedback": {"ok": "Goed! Hernieuwbare energie raakt niet op.", "nee": "Niet juist. Hernieuwbaar = onuitputtelijke bronnen zoals zon en wind."}}, {"text": "Welk probleem noemt de tekst voor het elektriciteitsnet?", "type": "Detail", "options": ["Het net is niet geschikt voor thuisopslag.", "Zonnepanelen leveren stroom van slechte kwaliteit.", "Te weinig stroom voor industrie.", "Het net raakt overbelast door te veel gelijktijdige invoeding."], "correct": 3, "highlight": "Het elektriciteitsnet is op sommige plekken overbelast doordat er te veel stroom tegelijk wordt ingevoed", "feedback": {"ok": "Prima! Overbelasting door te veel gelijktijdige invoeding.", "nee": "Niet correct. Alinea 4: overbelasting doordat er te veel stroom tegelijk wordt ingevoed."}}]}, {"topic": "Maatschappij", "title": "Vrijwilligerswerk in Nederland: wie doet het en waarom?", "paragraphs": ["Nederland heeft een sterke traditie van vrijwilligerswerk. Ongeveer vier op de tien Nederlanders doen regelmatig vrijwilligerswerk. Ze helpen bij sportverenigingen, zorginstellingen, buurthuizen of voedselbanken. Zonder vrijwilligers zouden veel maatschappelijke voorzieningen niet kunnen functioneren.", "Mensen doen vrijwilligerswerk om verschillende redenen. Sommigen willen iets terugdoen voor de samenleving, anderen willen nieuwe mensen ontmoeten of iets leren. Er zijn ook mensen die vrijwilligerswerk doen om werkervaring op te doen of om hun cv te versterken, vooral als ze werkloos zijn.", "Toch staat het vrijwilligerswerk in Nederland onder druk. Het aantal mensen dat zich opgeeft als vrijwilliger daalt langzaam. Organisaties merken dat mensen minder tijd willen vastleggen en liever kortdurend of eenmalig helpen. De verwachting dat iemand elke week beschikbaar is, schrikt velen af.", "Organisaties spelen hierop in door flexibeler te worden. Ze bieden projecten aan waarbij iemand één dag of een weekend helpt in plaats van een vaste wekelijkse verplichting. Zo hopen ze ook jongere generaties aan te trekken, die het moeilijk vinden om langdurige verplichtingen aan te gaan."], "questions": [{"text": "Hoeveel Nederlanders doen regelmatig vrijwilligerswerk?", "type": "Detail", "options": ["Acht op de tien", "Twee op de tien", "Één op de tien", "Vier op de tien"], "correct": 3, "highlight": "Ongeveer vier op de tien Nederlanders doen regelmatig vrijwilligerswerk", "feedback": {"ok": "Goed! Vier op de tien Nederlanders.", "nee": "Niet juist. Alinea 1: vier op de tien Nederlanders."}}, {"text": "Waarom doen werklozen vrijwilligerswerk?", "type": "Detail", "options": ["Ze worden door de overheid verplicht.", "Ze willen een eigen bedrijf starten.", "Ze worden er goed voor betaald.", "Ze willen werkervaring opdoen en hun cv versterken."], "correct": 3, "highlight": "vrijwilligerswerk doen om werkervaring op te doen of om hun cv te versterken, vooral als ze werkloos zijn", "feedback": {"ok": "Correct! Werkervaring opdoen en cv versterken.", "nee": "Niet correct. Alinea 2: werkervaring en cv versterken."}}, {"text": "Waarom daalt het aantal vrijwilligers?", "type": "Inferentie", "options": ["Vrijwilligerswerk is wettelijk beperkt.", "Er is minder behoefte aan vrijwilligers.", "Vrijwilligerswerk wordt slechter betaald.", "Mensen willen liever kortdurend helpen dan vaste verplichtingen."], "correct": 3, "highlight": "mensen minder tijd willen vastleggen en liever kortdurend of eenmalig helpen", "feedback": {"ok": "Juist! Mensen vermijden vaste, langdurige verplichtingen.", "nee": "Niet juist. Alinea 3: mensen willen liever kortdurend of eenmalig helpen."}}, {"text": "Wat betekent 'maatschappelijke voorzieningen' (alinea 1)?", "type": "Woordbetekenis", "options": ["Overheidsgebouwen", "Commerciële bedrijven", "Luxediensten voor rijken", "Diensten nuttig voor de samenleving"], "correct": 3, "highlight": "Zonder vrijwilligers zouden veel maatschappelijke voorzieningen niet kunnen functioneren", "feedback": {"ok": "Goed! Maatschappelijke voorzieningen zijn diensten voor de samenleving.", "nee": "Niet juist. Maatschappelijke voorzieningen zijn diensten die de samenleving ten goede komen."}}, {"text": "Hoe proberen organisaties meer vrijwilligers aan te trekken?", "type": "Detail", "options": ["Door vrijwilligerswerk verplicht te stellen.", "Door de minimumleeftijd te verlagen.", "Door hogere vergoedingen.", "Door flexibelere, kortdurende projecten."], "correct": 3, "highlight": "Ze bieden projecten aan waarbij iemand één dag of een weekend helpt", "feedback": {"ok": "Prima! Kortdurende, flexibele projecten.", "nee": "Niet correct. Alinea 4: kortdurende projecten zoals één dag of een weekend."}}]}, {"topic": "Economie", "title": "De boerenmarkt: nostalgie of echte trend?", "paragraphs": ["In veel Nederlandse steden en dorpen zijn boerenmarkten populairder dan ooit. Op deze markten verkopen lokale boeren en producenten direct aan de consument, zonder tussenkomst van supermarkten of groothandels. Je vindt er verse groenten, fruit, zuivel, vlees en ambachtelijke producten zoals kaas en jam.", "Mensen gaan naar de boerenmarkt om verschillende redenen. Sommigen willen weten waar hun eten vandaan komt en kiezen bewust voor lokale producten. Anderen genieten van de gezellige sfeer en de persoonlijke aandacht van de verkopers. En er zijn mensen die vinden dat producten op de boerenmarkt lekkerder smaken dan die uit de supermarkt.", "Toch zijn er ook kritische geluiden. Producten op de boerenmarkt zijn vaak duurder dan in de supermarkt. Niet iedereen kan zich dat veroorloven. Bovendien is het aanbod seizoensgebonden: in de winter zijn er minder verse producten beschikbaar dan in de zomer.", "Voor boeren biedt de markt een kans om een eerlijkere prijs te krijgen voor hun producten. In de reguliere supermarktwereld worden boeren soms onder druk gezet om hun producten voor een lage prijs te verkopen. Op de boerenmarkt kunnen ze zelf bepalen wat ze vragen en direct contact onderhouden met hun klanten."], "questions": [{"text": "Wat is kenmerkend voor een boerenmarkt?", "type": "Detail", "options": ["Er zijn alleen biologische producten.", "Het is een online marktplaats.", "Producten zijn altijd goedkoper dan in de supermarkt.", "Lokale producenten verkopen direct aan de consument."], "correct": 3, "highlight": "lokale boeren en producenten direct aan de consument, zonder tussenkomst van supermarkten of groothandels", "feedback": {"ok": "Goed! Direct van producent naar consument, zonder tussenpersoon.", "nee": "Niet juist. Alinea 1: lokale producenten verkopen direct aan de consument."}}, {"text": "Waarom gaan sommige mensen naar de boerenmarkt?", "type": "Detail", "options": ["Omdat er nooit rijen zijn.", "Omdat supermarkten te ver weg zijn.", "Omdat de producten altijd goedkoper zijn.", "Omdat ze willen weten waar hun eten vandaan komt."], "correct": 3, "highlight": "Sommigen willen weten waar hun eten vandaan komt en kiezen bewust voor lokale producten", "feedback": {"ok": "Correct! Ze willen weten waar hun eten vandaan komt.", "nee": "Niet correct. Alinea 2: sommigen willen weten waar hun eten vandaan komt."}}, {"text": "Wat is een nadeel van de boerenmarkt?", "type": "Detail", "options": ["Er is te weinig keuze.", "Er zijn geen verse producten beschikbaar.", "De markten zijn altijd overvol.", "Producten zijn vaak duurder dan in de supermarkt."], "correct": 3, "highlight": "Producten op de boerenmarkt zijn vaak duurder dan in de supermarkt", "feedback": {"ok": "Juist! De hogere prijs is een nadeel.", "nee": "Niet juist. Alinea 3: producten zijn vaak duurder dan in de supermarkt."}}, {"text": "Wat betekent 'seizoensgebonden' (alinea 3)?", "type": "Woordbetekenis", "options": ["Duurder in de winter", "Alleen 's zomers verkrijgbaar", "Het hele jaar beschikbaar", "Afhankelijk van het seizoen"], "correct": 3, "highlight": "het aanbod seizoensgebonden: in de winter zijn er minder verse producten beschikbaar", "feedback": {"ok": "Goed! Seizoensgebonden = afhankelijk van het seizoen.", "nee": "Niet juist. Seizoensgebonden betekent dat iets afhangt van het seizoen."}}, {"text": "Welk voordeel biedt de boerenmarkt voor boeren?", "type": "Inferentie", "options": ["Ze kunnen hun producten langer bewaren.", "Ze hoeven geen belasting te betalen.", "Ze kunnen meer producten verkopen dan via de supermarkt.", "Ze kunnen zelf de prijs bepalen en direct contact hebben met klanten."], "correct": 3, "highlight": "kunnen ze zelf bepalen wat ze vragen en direct contact onderhouden met hun klanten", "feedback": {"ok": "Prima! Zelf prijs bepalen en direct klantcontact.", "nee": "Niet correct. Alinea 4: boeren kunnen zelf de prijs bepalen en direct contact hebben met klanten."}}]}, {"topic": "Sport", "title": "Hardlopen in Nederland: voor iedereen?", "paragraphs": ["Hardlopen is een van de populairste sporten in Nederland. Meer dan drie miljoen Nederlanders lopen regelmatig hard. Je hebt er weinig voor nodig: een paar goede schoenen en een geschikte route. Daardoor is het een van de goedkoopste sporten die er zijn.", "De populariteit van hardlopen is de afgelopen jaren verder gegroeid. Grote evenementen zoals de Dam tot Damloop en de marathon van Rotterdam en Amsterdam trekken tienduizenden deelnemers en toeschouwers. Veel lopers trainen maandenlang om zo'n evenement te kunnen voltooien.", "Hardlopen heeft duidelijke gezondheidsvoordelen. Het versterkt het hart en de spieren, en helpt bij het op een gezond gewicht blijven. Maar er zijn ook risico's. Blessures zoals knieproblemen en spierblessures komen veel voor, vooral als mensen te snel te veel gaan lopen.", "Experts adviseren om rustig te beginnen en de trainingsintensiteit langzaam op te bouwen. Een goede warming-up en cooling-down zijn belangrijk, net als de juiste schoenen voor je loopstijl. Beginners kunnen het best starten met een loopprogramma dat afwisselt tussen lopen en wandelen."], "questions": [{"text": "Hoeveel Nederlanders lopen regelmatig hard?", "type": "Detail", "options": ["Meer dan vijf miljoen", "Meer dan een miljoen", "Meer dan twee miljoen", "Meer dan drie miljoen"], "correct": 3, "highlight": "Meer dan drie miljoen Nederlanders lopen regelmatig hard", "feedback": {"ok": "Goed! Meer dan drie miljoen Nederlanders.", "nee": "Niet juist. Alinea 1: meer dan drie miljoen Nederlanders."}}, {"text": "Waarom is hardlopen een van de goedkoopste sporten?", "type": "Inferentie", "options": ["Sportschoenen zijn in Nederland goedkoop.", "Je kunt gratis trainen bij een coach.", "Je hebt alleen goede schoenen en een route nodig.", "Je hebt een duur lidmaatschap nodig."], "correct": 2, "highlight": "Je hebt er weinig voor nodig: een paar goede schoenen en een geschikte route", "feedback": {"ok": "Correct! Je hebt weinig materiaal nodig.", "nee": "Niet correct. Alinea 1: je hebt alleen goede schoenen en een route nodig."}}, {"text": "Wat zijn risico's van hardlopen?", "type": "Detail", "options": ["Gewrichtsversterking.", "Oververhitting in de winter.", "Te weinig calorieën verbranden.", "Knieproblemen en spierblessures."], "correct": 3, "highlight": "Blessures zoals knieproblemen en spierblessures komen veel voor", "feedback": {"ok": "Juist! Knieproblemen en spierblessures zijn veelvoorkomende risico's.", "nee": "Niet juist. Alinea 3: knieproblemen en spierblessures komen veel voor."}}, {"text": "Wat adviseren experts voor beginners?", "type": "Detail", "options": ["Alleen lopen op een loopband.", "Direct starten met een marathon.", "Elke dag minimaal tien kilometer lopen.", "Beginnen met een programma dat afwisselt tussen lopen en wandelen."], "correct": 3, "highlight": "Beginners kunnen het best starten met een loopprogramma dat afwisselt tussen lopen en wandelen", "feedback": {"ok": "Goed! Afwisselen tussen lopen en wandelen voor beginners.", "nee": "Niet juist. Alinea 4: een programma dat afwisselt tussen lopen en wandelen."}}, {"text": "Wat betekent 'trainingsintensiteit' (alinea 4)?", "type": "Woordbetekenis", "options": ["De kosten van je training", "Hoe lang je traint", "Hoe vaak je per week traint", "Hoe zwaar of intensief je traint"], "correct": 3, "highlight": "de trainingsintensiteit langzaam op te bouwen", "feedback": {"ok": "Goed! Trainingsintensiteit = hoe zwaar of intensief je traint.", "nee": "Niet juist. Trainingsintensiteit verwijst naar de zwaarte van je training."}}]}, {"topic": "Geschiedenis", "title": "Anne Frank: een verhaal dat de wereld raakte", "paragraphs": ["Anne Frank was een joods meisje dat tijdens de Tweede Wereldoorlog samen met haar familie ondergedoken zat in een achterhuis in Amsterdam. Ze was dertien jaar oud toen ze begon met het bijhouden van een dagboek. Daarin schreef ze over haar dagelijkse leven, haar dromen en haar angsten.", "Het achterhuis bevond zich op de Prinsengracht in Amsterdam. Twee jaar lang leefde de familie Frank er in het geheim, samen met vier andere onderduikers. Ze konden het gebouw niet verlaten en waren afhankelijk van hulp van vertrouwde medewerkers. In augustus 1944 werden ze ontdekt en gearresteerd.", "Anne Frank overleefde de oorlog niet. Ze stierf in februari 1945 in het concentratiekamp Bergen-Belsen, kort voor de bevrijding. Haar vader Otto Frank was de enige die de oorlog overleefde. Na de bevrijding liet hij het dagboek van Anne publiceren.", "Het dagboek van Anne Frank is inmiddels in meer dan tachtig talen vertaald en wereldwijd meer dan dertig miljoen keer verkocht. Het Anne Frank Huis in Amsterdam trekt elk jaar meer dan een miljoen bezoekers. Het verhaal van Anne Frank herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid."], "questions": [{"text": "Hoe oud was Anne Frank toen ze begon met haar dagboek?", "type": "Detail", "options": ["Veertien jaar", "Elf jaar", "Dertien jaar", "Twaalf jaar"], "correct": 2, "highlight": "Ze was dertien jaar oud toen ze begon met het bijhouden van een dagboek", "feedback": {"ok": "Goed! Anne was dertien jaar oud.", "nee": "Niet juist. Alinea 1: ze was dertien jaar oud."}}, {"text": "Waar bevond het achterhuis zich?", "type": "Detail", "options": ["In Rotterdam.", "In Utrecht.", "Op de Keizersgracht in Amsterdam.", "Op de Prinsengracht in Amsterdam."], "correct": 3, "highlight": "Het achterhuis bevond zich op de Prinsengracht in Amsterdam", "feedback": {"ok": "Correct! Het achterhuis stond op de Prinsengracht.", "nee": "Niet correct. Alinea 2: op de Prinsengracht in Amsterdam."}}, {"text": "Hoe lang leefde de familie Frank ondergedoken?", "type": "Detail", "options": ["Vier jaar", "Drie jaar", "Een jaar", "Twee jaar"], "correct": 3, "highlight": "Twee jaar lang leefde de familie Frank er in het geheim", "feedback": {"ok": "Juist! Twee jaar lang.", "nee": "Niet juist. Alinea 2: twee jaar lang."}}, {"text": "Wat betekent 'onverdraagzaamheid' (alinea 4)?", "type": "Woordbetekenis", "options": ["Het niet kunnen verdragen van pijn", "Een houding van vriendelijkheid", "Een ziekte die veel pijn veroorzaakt", "Het niet accepteren van anderen die anders zijn"], "correct": 3, "highlight": "de gevaren van discriminatie en onverdraagzaamheid", "feedback": {"ok": "Goed! Onverdraagzaamheid = het niet accepteren van mensen die anders zijn.", "nee": "Niet juist. Onverdraagzaamheid betekent het niet dulden van anderen."}}, {"text": "Wat is het belang van het verhaal van Anne Frank?", "type": "Hoofdgedachte", "options": ["Het is de beste manier om Duits te leren.", "Het laat zien hoe Amsterdam er vroeger uitzag.", "Het toont aan dat dagboeken schrijven nuttig is.", "Het herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid."], "correct": 3, "highlight": "Het verhaal van Anne Frank herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid", "feedback": {"ok": "Prima! Het verhaal waarschuwt voor discriminatie en onverdraagzaamheid.", "nee": "Niet correct. Alinea 4: het verhaal herinnert aan de gevaren van discriminatie."}}]}, {"topic": "Gezondheidszorg", "title": "De huisarts: eerste aanspreekpunt in de zorg", "paragraphs": ["In Nederland is de huisarts voor de meeste mensen het eerste aanspreekpunt als ze ziek zijn of klachten hebben. De huisarts kent zijn patiënten vaak al jaren en kan daardoor snel inschatten of iemand doorverwezen moet worden naar een specialist of dat een eenvoudige behandeling volstaat.", "Nederland heeft een poortwachterssysteem in de gezondheidszorg. Dit betekent dat je bijna altijd eerst naar de huisarts moet voordat je een specialist kunt bezoeken. Dit systeem voorkomt dat specialisten overbelast raken met klachten die ook door de huisarts behandeld kunnen worden.", "De werkdruk voor huisartsen is de afgelopen jaren sterk gestegen. Er zijn te weinig huisartsen voor het groeiende aantal patiënten. Wachttijden bij huisartsenpraktijken lopen op, en steeds meer mensen hebben moeite om een vaste huisarts te vinden. Dit is een groeiend probleem in Nederland.", "Om de druk te verlichten, werken huisartsenpraktijken steeds vaker samen in grotere gezondheidscentra. Hier werken ook praktijkverpleegkundigen, diëtisten en fysiotherapeuten. Hierdoor kunnen patiënten voor meer soorten zorg terecht op één plek, en wordt de werkdruk beter verdeeld."], "questions": [{"text": "Wat is de rol van de huisarts?", "type": "Detail", "options": ["De huisarts werkt alleen in ziekenhuizen.", "De huisarts schrijft altijd medicijnen voor.", "De huisarts vervangt specialisten volledig.", "De huisarts is het eerste aanspreekpunt bij klachten."], "correct": 3, "highlight": "de huisarts voor de meeste mensen het eerste aanspreekpunt", "feedback": {"ok": "Goed! De huisarts is het eerste aanspreekpunt.", "nee": "Niet juist. Alinea 1: de huisarts is het eerste aanspreekpunt bij klachten."}}, {"text": "Wat is het poortwachterssysteem?", "type": "Woordbetekenis", "options": ["Een systeem waarbij patiënten zelf een specialist kiezen.", "Een systeem waarbij specialisten altijd direct bereikbaar zijn.", "Een systeem waarbij zorgverzekeringen de toegang regelen.", "Een systeem waarbij je eerst naar de huisarts moet voordat je een specialist kunt bezoeken."], "correct": 3, "highlight": "je bijna altijd eerst naar de huisarts moet voordat je een specialist kunt bezoeken", "feedback": {"ok": "Correct! Eerst naar de huisarts, dan eventueel naar de specialist.", "nee": "Niet correct. Alinea 2: je moet eerst naar de huisarts."}}, {"text": "Wat is een groeiend probleem bij huisartsen?", "type": "Detail", "options": ["Patiënten vertrouwen huisartsen niet meer.", "Huisartsen verdienen te weinig.", "Huisartsenpraktijken zijn te groot geworden.", "Er zijn te weinig huisartsen voor het groeiende aantal patiënten."], "correct": 3, "highlight": "Er zijn te weinig huisartsen voor het groeiende aantal patiënten", "feedback": {"ok": "Juist! Te weinig huisartsen voor te veel patiënten.", "nee": "Niet juist. Alinea 3: er zijn te weinig huisartsen."}}, {"text": "Hoe verlichten huisartsenpraktijken de werkdruk?", "type": "Detail", "options": ["Door alleen nog digitale consulten aan te bieden.", "Door patiënten direct naar de spoedeisende hulp te sturen.", "Door minder patiënten aan te nemen.", "Door samen te werken in grotere gezondheidscentra."], "correct": 3, "highlight": "huisartsenpraktijken steeds vaker samen in grotere gezondheidscentra", "feedback": {"ok": "Goed! Samenwerken in gezondheidscentra verlicht de druk.", "nee": "Niet juist. Alinea 4: samenwerken in grotere gezondheidscentra."}}, {"text": "Welk voordeel hebben gezondheidscentra voor patiënten?", "type": "Inferentie", "options": ["Ze krijgen altijd dezelfde huisarts.", "Ze hoeven nooit meer naar een ziekenhuis.", "Ze kunnen goedkoper zorg krijgen.", "Ze kunnen voor meer soorten zorg terecht op één plek."], "correct": 3, "highlight": "kunnen patiënten voor meer soorten zorg terecht op één plek", "feedback": {"ok": "Prima! Meer soorten zorg op één plek.", "nee": "Niet correct. Alinea 4: patiënten kunnen voor meer soorten zorg terecht op één plek."}}]}, {"topic": "Reizen", "title": "Toerisme in Amsterdam: te veel of net genoeg?", "paragraphs": ["Amsterdam is een van de meest bezochte steden van Europa. Elk jaar komen er meer dan twintig miljoen toeristen naar de stad. Ze komen voor de grachten, de musea zoals het Rijksmuseum en het Van Gogh Museum, de bruine kroegen en de fietscultuur. De stad heeft een unieke sfeer die mensen van over de hele wereld aantrekt.", "Maar de grote toestroom van toeristen zorgt ook voor problemen. Bewoners klagen over drukte, lawaai en stijgende huurprijzen. Populaire plekken zijn soms zo vol dat bewoners zich in hun eigen wijk niet meer thuis voelen. Er is ook overlast van groepen toeristen die zich misdragen.", "De gemeente Amsterdam heeft verschillende maatregelen genomen om het toerisme te beperken. Nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum. Toeristen die in de stad overnachten, betalen een hogere toeristenbelasting. En sommige populaire attracties werken alleen nog met reserveringen vooraf.", "Niet iedereen is het eens met de aanpak van de gemeente. Horeca en winkels die van toeristen afhankelijk zijn, vrezen voor hun omzet. Ze zeggen dat toerisme ook veel oplevert voor de stad: werkgelegenheid, belastinginkomsten en internationale bekendheid. Het debat over de balans tussen leefbaarheid en toerisme gaat nog altijd door."], "questions": [{"text": "Hoeveel toeristen bezoeken Amsterdam elk jaar?", "type": "Detail", "options": ["Meer dan vijfentwintig miljoen", "Meer dan tien miljoen", "Meer dan vijftien miljoen", "Meer dan twintig miljoen"], "correct": 3, "highlight": "Elk jaar komen er meer dan twintig miljoen toeristen naar de stad", "feedback": {"ok": "Goed! Meer dan twintig miljoen toeristen per jaar.", "nee": "Niet juist. Alinea 1: meer dan twintig miljoen toeristen per jaar."}}, {"text": "Waarover klagen bewoners van Amsterdam?", "type": "Detail", "options": ["Over slechte bereikbaarheid van de stad.", "Over de hoge kosten van musea.", "Over te weinig toeristen in de winter.", "Over drukte, lawaai en stijgende huurprijzen."], "correct": 3, "highlight": "Bewoners klagen over drukte, lawaai en stijgende huurprijzen", "feedback": {"ok": "Correct! Drukte, lawaai en stijgende huurprijzen.", "nee": "Niet correct. Alinea 2: bewoners klagen over drukte, lawaai en stijgende huurprijzen."}}, {"text": "Welke maatregel heeft Amsterdam genomen?", "type": "Detail", "options": ["Toeristen mogen maar twee dagen blijven.", "Gratis openbaar vervoer voor bewoners.", "Alle attracties zijn gratis voor bewoners.", "Nieuwe hotels mogen niet meer worden gebouwd in het centrum."], "correct": 3, "highlight": "Nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum", "feedback": {"ok": "Juist! Geen nieuwe hotels in het centrum.", "nee": "Niet juist. Alinea 3: nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum."}}, {"text": "Wat betekent 'toeristenbelasting' (alinea 3)?", "type": "Woordbetekenis", "options": ["Een belasting op souvenirs.", "Een belasting op vliegtickets naar Amsterdam.", "Een belasting die toeristen betalen als ze de stad beschadigen.", "Een belasting die toeristen betalen als ze in de stad overnachten."], "correct": 3, "highlight": "Toeristen die in de stad overnachten, betalen een hogere toeristenbelasting", "feedback": {"ok": "Goed! Toeristenbelasting = een belasting voor toeristen die overnachten.", "nee": "Niet juist. Toeristenbelasting is een belasting die je betaalt als je in een stad overnacht."}}, {"text": "Waarom zijn horeca en winkels tegen het beperken van toerisme?", "type": "Inferentie", "options": ["Ze denken dat bewoners van de toeristen profiteren.", "Ze willen meer hotels bouwen.", "Ze vinden dat toeristen geen overlast geven.", "Ze vrezen voor hun omzet en zeggen dat toerisme veel oplevert."], "correct": 3, "highlight": "vrezen voor hun omzet. Ze zeggen dat toerisme ook veel oplevert voor de stad", "feedback": {"ok": "Prima! Ze vrezen voor hun omzet en noemen de voordelen van toerisme.", "nee": "Niet correct. Alinea 4: horeca en winkels vrezen voor hun omzet."}}]}, {"topic": "Wetenschap", "title": "Slaap: waarom je er niet zonder kunt", "paragraphs": ["Slapen is een basisbehoefte van het menselijk lichaam, net als eten en drinken. Tijdens de slaap herstelt het lichaam zich: spieren worden gerepareerd, het immuunsysteem wordt versterkt en herinneringen worden verwerkt en opgeslagen. Wetenschappers zijn het erover eens dat volwassenen gemiddeld zeven tot negen uur slaap per nacht nodig hebben.", "Toch slaapt een groot deel van de bevolking te weinig. Werkdruk, schermgebruik voor het slapengaan en stress zijn veelgenoemde oorzaken. Blauw licht van telefoons en tablets houdt de hersenen actief en verstoort de aanmaak van het slaaphormoon melatonine. Hierdoor duurt het langer voordat mensen in slaap vallen.", "Chronisch slaaptekort heeft ernstige gevolgen. Het verhoogt het risico op hart- en vaatziekten, diabetes en depressie. Ook het geheugen en de concentratie worden aangetast. Mensen die structureel te weinig slapen, functioneren overdag slechter en maken vaker fouten.", "Slaapexperts geven verschillende tips om beter te slapen. Ga op vaste tijden naar bed en sta op vaste tijden op, ook in het weekend. Vermijd schermen een uur voor het slapengaan. Zorg voor een koele, donkere en rustige slaapkamer. En beperk cafeïne in de namiddag en avond."], "questions": [{"text": "Hoeveel uur slaap hebben volwassenen gemiddeld nodig?", "type": "Detail", "options": ["Acht tot tien uur", "Vijf tot zeven uur", "Zes tot acht uur", "Zeven tot negen uur"], "correct": 3, "highlight": "volwassenen gemiddeld zeven tot negen uur slaap per nacht nodig hebben", "feedback": {"ok": "Goed! Zeven tot negen uur per nacht.", "nee": "Niet juist. Alinea 1: zeven tot negen uur slaap per nacht."}}, {"text": "Wat doet blauw licht van schermen met je lichaam?", "type": "Detail", "options": ["Het verbetert de geheugenopslag.", "Het verstoort de aanmaak van melatonine.", "Het versterkt het immuunsysteem.", "Het helpt je sneller in slaap vallen."], "correct": 1, "highlight": "Blauw licht van telefoons en tablets houdt de hersenen actief en verstoort de aanmaak van het slaaphormoon melatonine", "feedback": {"ok": "Correct! Blauw licht verstoort de aanmaak van melatonine.", "nee": "Niet correct. Alinea 2: blauw licht verstoort de aanmaak van melatonine."}}, {"text": "Welk gevolg heeft chronisch slaaptekort?", "type": "Detail", "options": ["Je hebt minder honger.", "Je hebt minder dromen.", "Je wordt energieker overdag.", "Het verhoogt het risico op hart- en vaatziekten en depressie."], "correct": 3, "highlight": "Het verhoogt het risico op hart- en vaatziekten, diabetes en depressie", "feedback": {"ok": "Juist! Slaaptekort verhoogt het risico op ernstige aandoeningen.", "nee": "Niet juist. Alinea 3: slaaptekort verhoogt het risico op hart- en vaatziekten en depressie."}}, {"text": "Wat betekent 'chronisch' (alinea 3)?", "type": "Woordbetekenis", "options": ["Plotseling en onverwacht", "Ernstig en ongeneeslijk", "Eenmalig en tijdelijk", "Langdurig en regelmatig terugkerend"], "correct": 3, "highlight": "Chronisch slaaptekort heeft ernstige gevolgen", "feedback": {"ok": "Goed! Chronisch = langdurig en regelmatig terugkerend.", "nee": "Niet juist. Chronisch betekent langdurig en structureel aanwezig."}}, {"text": "Wat raden slaapexperts aan voor een betere nachtrust?", "type": "Detail", "options": ["Cafeïne drinken voor het slapengaan.", "Elke nacht een ander slaaptijdstip kiezen.", "Overdag zo lang mogelijk slapen.", "Op vaste tijden naar bed gaan en schermen vermijden voor het slapengaan."], "correct": 3, "highlight": "Ga op vaste tijden naar bed en sta op vaste tijden op", "feedback": {"ok": "Prima! Vaste tijden en schermen vermijden zijn de adviezen.", "nee": "Niet correct. Alinea 4: vaste tijden en schermen vermijden voor het slapengaan."}}]}, {"topic": "Energie", "title": "Windenergie in Nederland: wind mee of tegenwind?", "paragraphs": ["Nederland is een van de windrijkste landen van Europa. Met name langs de kust en op zee waait het bijna altijd. Het is dan ook niet verrassend dat windenergie een belangrijke rol speelt in de Nederlandse energietransitie. De overheid heeft als doel om in 2030 zeventig procent van alle elektriciteit uit hernieuwbare bronnen op te wekken.", "Er zijn twee soorten windparken: windparken op land en windparken op zee. Windparken op zee, ook wel 'offshore' windparken genoemd, hebben grote voordelen. Ze staan verder van bewoonde gebieden af, de wind waait er constanter en de turbines kunnen groter zijn. Nadeel is dat ze duurder zijn om te bouwen en te onderhouden.", "Windparken op land stuiten soms op weerstand van omwonenden. Mensen klagen over geluidsoverlast, slagschaduw — het flikkeren van schaduwen als de wieken draaien — en het effect op het landschap. Gemeenten moeten bij het plannen van windparken rekening houden met de belangen van omwonenden.", "Ondanks de bezwaren groeit het aantal windturbines in Nederland snel. Windenergie is inmiddels een van de goedkoopste manieren om elektriciteit op te wekken. En met de stijgende energieprijzen en de noodzaak om minder afhankelijk te zijn van fossiele brandstoffen, wordt investeren in wind steeds aantrekkelijker."], "questions": [{"text": "Wat is het doel van de Nederlandse overheid voor 2030?", "type": "Detail", "options": ["Alle kolencentrales sluiten.", "50% minder energie gebruiken dan in 2020.", "Alle energie uit windmolens halen.", "70% van alle elektriciteit uit hernieuwbare bronnen opwekken."], "correct": 3, "highlight": "De overheid heeft als doel om in 2030 zeventig procent van alle elektriciteit uit hernieuwbare bronnen op te wekken", "feedback": {"ok": "Goed! 70% hernieuwbare elektriciteit in 2030.", "nee": "Niet juist. Alinea 1: het doel is 70% hernieuwbare elektriciteit in 2030."}}, {"text": "Wat is een voordeel van windparken op zee?", "type": "Detail", "options": ["Ze zijn makkelijker te onderhouden.", "Ze zijn goedkoper te bouwen.", "Ze produceren meer elektriciteit in de zomer.", "Ze staan verder van bewoonde gebieden en de wind waait er constanter."], "correct": 3, "highlight": "Ze staan verder van bewoonde gebieden af, de wind waait er constanter en de turbines kunnen groter zijn", "feedback": {"ok": "Correct! Verder van bewoning, constantere wind en grotere turbines.", "nee": "Niet correct. Alinea 2: verder van bewoning, constantere wind, grotere turbines."}}, {"text": "Wat is 'slagschaduw' (alinea 3)?", "type": "Woordbetekenis", "options": ["De schaduw van grote gebouwen", "Een technisch probleem met windturbines", "Geluid dat windturbines produceren", "Het flikkeren van schaduwen als de wieken draaien"], "correct": 3, "highlight": "slagschaduw — het flikkeren van schaduwen als de wieken draaien", "feedback": {"ok": "Goed! Slagschaduw = flikkerende schaduwen van draaiende wieken.", "nee": "Niet juist. Alinea 3 legt slagschaduw uit als het flikkeren van schaduwen."}}, {"text": "Wat klagen omwonenden over bij windparken op land?", "type": "Detail", "options": ["Het gebrek aan windturbines in hun buurt.", "De gevaren voor vogels.", "De hoge kosten van stroom.", "Geluidsoverlast, slagschaduw en effect op het landschap."], "correct": 3, "highlight": "Mensen klagen over geluidsoverlast, slagschaduw", "feedback": {"ok": "Juist! Geluidsoverlast, slagschaduw en landschapseffect.", "nee": "Niet juist. Alinea 3: klachten over geluidsoverlast, slagschaduw en effect op het landschap."}}, {"text": "Waarom wordt investeren in wind steeds aantrekkelijker?", "type": "Inferentie", "options": ["Omdat de overheid subsidies afschaft.", "Omdat windturbines steeds kleiner worden.", "Omdat windenergie de enige hernieuwbare energiebron is.", "Vanwege stijgende energieprijzen en de wens minder afhankelijk te zijn van fossiele brandstoffen."], "correct": 3, "highlight": "met de stijgende energieprijzen en de noodzaak om minder afhankelijk te zijn van fossiele brandstoffen", "feedback": {"ok": "Prima! Stijgende prijzen en minder fossiele brandstoffen.", "nee": "Niet correct. Alinea 4: stijgende energieprijzen en minder afhankelijkheid van fossiele brandstoffen."}}]}, {"topic": "Dieren", "title": "De wolf is terug in Nederland", "paragraphs": ["Na meer dan honderd jaar afwezigheid is de wolf teruggekeerd in Nederland. De eerste wolf werd in 2015 gesignaleerd op de Veluwe. Sindsdien hebben zich meerdere wolven gevestigd en zijn er zelfs roedels — families van wolven — ontstaan. Het is een bijzondere ontwikkeling in een dichtbevolkt land als Nederland.", "De terugkeer van de wolf zorgt voor enthousiasme bij natuurliefhebbers, maar ook voor bezorgdheid bij boeren. Wolven vallen schapen, geiten en soms koeien aan. Boeren worden financieel gecompenseerd als hun dieren door een wolf worden gedood, maar ze klagen dat de vergoedingen niet altijd voldoende zijn en dat het bureaucratische proces te lang duurt.", "Om aanvallen te voorkomen, worden boeren aangeraden om elektrische rasters te plaatsen rond hun kuddes. De overheid subsidieert een deel van de kosten hiervoor. Ook worden waakhonden ingezet om het vee te beschermen. Maar in een land met zoveel wegen en bebouwing is het moeilijk om wolven en vee volledig van elkaar te scheiden.", "Biologen wijzen erop dat de wolf een belangrijke rol speelt in het ecosysteem. Als roofdier houdt hij populaties van herten en reeën in evenwicht. Dit heeft op zijn beurt een positief effect op de vegetatie, omdat de grazers minder vrij rondlopen. De terugkeer van de wolf is daarmee niet alleen een uitdaging, maar ook een kans voor de Nederlandse natuur."], "questions": [{"text": "Wanneer werd de eerste wolf gesignaleerd in Nederland?", "type": "Detail", "options": ["In 2018", "In 2010", "In 2013", "In 2015"], "correct": 3, "highlight": "De eerste wolf werd in 2015 gesignaleerd op de Veluwe", "feedback": {"ok": "Goed! De eerste wolf werd in 2015 gesignaleerd.", "nee": "Niet juist. Alinea 1: de eerste wolf werd in 2015 gesignaleerd."}}, {"text": "Waarover klagen boeren bij de financiële compensatie?", "type": "Detail", "options": ["Ze krijgen geen compensatie voor aanvallen op koeien.", "De vergoedingen zijn te hoog.", "De overheid betaalt alleen voor schapen.", "De vergoedingen zijn niet altijd voldoende en het proces duurt te lang."], "correct": 3, "highlight": "de vergoedingen niet altijd voldoende zijn en dat het bureaucratische proces te lang duurt", "feedback": {"ok": "Correct! Onvoldoende vergoedingen en een traag proces.", "nee": "Niet correct. Alinea 2: de vergoedingen zijn soms onvoldoende en het proces duurt te lang."}}, {"text": "Wat wordt aangeraden om aanvallen van wolven te voorkomen?", "type": "Detail", "options": ["Wolven vangen en verplaatsen.", "Jagers inzetten om wolven te verjagen.", "Vee 's nachts binnenhalen.", "Elektrische rasters plaatsen rond kuddes."], "correct": 3, "highlight": "worden boeren aangeraden om elektrische rasters te plaatsen rond hun kuddes", "feedback": {"ok": "Juist! Elektrische rasters zijn de aanbevolen maatregel.", "nee": "Niet juist. Alinea 3: elektrische rasters plaatsen rond de kuddes."}}, {"text": "Wat betekent 'ecosysteem' (alinea 4)?", "type": "Woordbetekenis", "options": ["Een beschermd bosgebied", "Een gebied met alleen wilde dieren", "Een wetenschappelijk laboratorium", "Het geheel van levende wezens en hun omgeving die samen functioneren"], "correct": 3, "highlight": "de wolf een belangrijke rol speelt in het ecosysteem", "feedback": {"ok": "Goed! Een ecosysteem is het geheel van levende wezens en hun omgeving.", "nee": "Niet juist. Een ecosysteem is het geheel van levende organismen en hun leefomgeving."}}, {"text": "Welk positief effect heeft de wolf op de natuur?", "type": "Inferentie", "options": ["De wolf helpt boeren door kleine dieren te verjagen.", "De wolf vermindert het aantal auto-ongelukken met wilde dieren.", "De wolf eet insecten die schadelijk zijn voor planten.", "De wolf houdt herten- en reepopulaties in evenwicht, wat goed is voor de vegetatie."], "correct": 3, "highlight": "houdt hij populaties van herten en reeën in evenwicht. Dit heeft op zijn beurt een positief effect op de vegetatie", "feedback": {"ok": "Prima! De wolf reguleert grazers, wat de vegetatie ten goede komt.", "nee": "Niet correct. Alinea 4: de wolf houdt herten- en reepopulaties in evenwicht."}}]}, {"topic": "Winkelen", "title": "De opkomst van online shoppen in Nederland", "paragraphs": ["Nederland behoort tot de landen met de hoogste percentages online shoppers in Europa. Bijna tachtig procent van de Nederlanders koopt regelmatig iets via internet. De coronapandemie heeft deze trend versneld: veel mensen die voorheen altijd in de winkel kochten, ontdekten het gemak van thuisbezorgd winkelen.", "Het succes van online winkelen heeft grote gevolgen voor de fysieke winkelstraat. Veel winkels sloten hun deuren, waardoor leegstand in binnensteden een groeiend probleem is geworden. Gemeenten en ondernemers zoeken naar manieren om winkelgebieden aantrekkelijk te houden, bijvoorbeeld door meer horeca en beleving aan te bieden.", "Bezorgdiensten en pakketbedrijven draaien op volle toeren. Elke dag rijden er duizenden bestelbusjes door Nederlandse wijken om pakketten af te leveren. Dit leidt tot meer verkeer en uitstoot in woonwijken. Steden zoals Amsterdam en Utrecht experimenteren met elektrische bezorgfietsen en pakketpunten om de overlast te verminderen.", "Toch blijft de fysieke winkel voor veel mensen aantrekkelijk. Kleding passen, producten voelen en direct meenemen zijn voordelen die online shoppen niet kan bieden. Steeds meer succesvolle webwinkels openen ook een fysieke winkel, omdat ze merken dat klanten graag beide ervaringen combineren."], "questions": [{"text": "Hoeveel procent van de Nederlanders koopt regelmatig online?", "type": "Detail", "options": ["Bijna zestig procent", "Bijna vijftig procent", "Bijna negentig procent", "Bijna tachtig procent"], "correct": 3, "highlight": "Bijna tachtig procent van de Nederlanders koopt regelmatig iets via internet", "feedback": {"ok": "Goed! Bijna tachtig procent.", "nee": "Niet juist. Alinea 1: bijna tachtig procent koopt regelmatig online."}}, {"text": "Wat is een gevolg van online winkelen voor de winkelstraat?", "type": "Detail", "options": ["Meer mensen gaan winkelen in het centrum.", "Winkels worden groter.", "Leegstand in binnensteden is een groeiend probleem geworden.", "Winkeliers verdienen meer door hogere prijzen."], "correct": 2, "highlight": "waardoor leegstand in binnensteden een groeiend probleem is geworden", "feedback": {"ok": "Correct! Leegstand in binnensteden is een gevolg.", "nee": "Niet correct. Alinea 2: leegstand in binnensteden is een groeiend probleem."}}, {"text": "Hoe proberen steden de overlast van bezorgdiensten te verminderen?", "type": "Detail", "options": ["Door online winkelen te verbieden.", "Door extra parkeerplaatsen te bouwen.", "Door meer bestelbusjes toe te staan.", "Door elektrische bezorgfietsen en pakketpunten te gebruiken."], "correct": 3, "highlight": "Steden zoals Amsterdam en Utrecht experimenteren met elektrische bezorgfietsen en pakketpunten", "feedback": {"ok": "Juist! Elektrische fietsen en pakketpunten helpen de overlast te verminderen.", "nee": "Niet juist. Alinea 3: elektrische bezorgfietsen en pakketpunten."}}, {"text": "Wat betekent 'leegstand' (alinea 2)?", "type": "Woordbetekenis", "options": ["Een winkel met veel klanten", "Te veel producten op voorraad", "Panden die leeg staan omdat er geen huurder voor is", "Een straat zonder verkeer"], "correct": 2, "highlight": "leegstand in binnensteden een groeiend probleem", "feedback": {"ok": "Goed! Leegstand = panden die leeg staan zonder huurder.", "nee": "Niet juist. Leegstand betekent dat panden leeg staan omdat er geen huurder voor gevonden wordt."}}, {"text": "Waarom openen succesvolle webwinkels ook een fysieke winkel?", "type": "Inferentie", "options": ["Omdat online winkelen te duur is geworden.", "Omdat klanten graag beide ervaringen combineren.", "Omdat de overheid dit verplicht stelt.", "Omdat online adverteren niet meer werkt."], "correct": 1, "highlight": "klanten graag beide ervaringen combineren", "feedback": {"ok": "Prima! Klanten willen zowel online als in de winkel kunnen winkelen.", "nee": "Niet correct. Alinea 4: klanten combineren graag de online en fysieke winkelervaring."}}]}, {"topic": "Klimaat", "title": "Droogte in Nederland: een nieuw normaal?", "paragraphs": ["Nederland staat bekend om zijn regenachtige klimaat, maar de afgelopen jaren hebben droge zomers steeds vaker voor problemen gezorgd. In 2018 en 2022 was er sprake van extreme droogte die leidde tot oogstschade bij boeren, lage waterstanden in rivieren en gevaar voor branden in natuurgebieden.", "De droogte heeft grote gevolgen voor de landbouw. Gewassen verdrogen, grasland verschraalt en boeren moeten extra irrigeren om hun land productief te houden. Dit vergroot het waterverbruik, terwijl er juist minder water beschikbaar is. Sommige boeren overwegen hun gewassen aan te passen aan het droger wordende klimaat.", "Ook de natuur lijdt onder de droogte. Veengebieden, die normaal gesproken veel water vasthouden, drogen uit en kunnen gaan smeulen. Eenmaal aangestoken zijn veenbrandjes moeilijk te blussen. Bovendien stoot uitdrogend veen grote hoeveelheden CO2 uit, wat de klimaatverandering verder versterkt.", "Waterbeheerders en beleidsmakers zoeken naar oplossingen. Het beter vasthouden van regenwater, het verminderen van waterverbruik en het herstel van natuurlijke waterbergingsgebieden zijn mogelijke maatregelen. Experts waarschuwen dat Nederland zich structureel moet aanpassen aan een droger klimaat, ook al is de jaarlijkse regenval gemiddeld nog steeds relatief hoog."], "questions": [{"text": "In welke jaren was er sprake van extreme droogte in Nederland?", "type": "Detail", "options": ["In 2015 en 2019", "In 2019 en 2021", "In 2016 en 2020", "In 2018 en 2022"], "correct": 3, "highlight": "In 2018 en 2022 was er sprake van extreme droogte", "feedback": {"ok": "Goed! In 2018 en 2022 was er extreme droogte.", "nee": "Niet juist. Alinea 1: in 2018 en 2022 was er extreme droogte."}}, {"text": "Wat is een gevolg van droogte voor de landbouw?", "type": "Detail", "options": ["Boeren hoeven minder te werken.", "De oogst wordt groter door warmte.", "Er is meer water beschikbaar voor irrigatie.", "Gewassen verdrogen en boeren moeten extra irrigeren."], "correct": 3, "highlight": "Gewassen verdrogen, grasland verschraalt en boeren moeten extra irrigeren", "feedback": {"ok": "Correct! Gewassen verdrogen en boeren irrigeren meer.", "nee": "Niet correct. Alinea 2: gewassen verdrogen en boeren moeten extra irrigeren."}}, {"text": "Waarom zijn veenbrandjes gevaarlijk voor het klimaat?", "type": "Inferentie", "options": ["Ze verspreiden giftige stoffen in het water.", "Ze maken het moeilijk om te ademen in de omgeving.", "Ze veroorzaken overstromingen.", "Uitdrogend veen stoot grote hoeveelheden CO2 uit."], "correct": 3, "highlight": "stoot uitdrogend veen grote hoeveelheden CO2 uit, wat de klimaatverandering verder versterkt", "feedback": {"ok": "Juist! Uitdrogend veen stoot CO2 uit en versterkt de klimaatverandering.", "nee": "Niet juist. Alinea 3: uitdrogend veen stoot CO2 uit."}}, {"text": "Wat betekent 'waterberging' (alinea 4)?", "type": "Woordbetekenis", "options": ["Het zuiveren van drinkwater", "Het laten wegstromen van overtollig water", "Het opslaan en vasthouden van water", "Het meten van de waterstand in rivieren"], "correct": 2, "highlight": "het herstel van natuurlijke waterbergingsgebieden", "feedback": {"ok": "Goed! Waterberging = het opslaan en vasthouden van water.", "nee": "Niet juist. Waterberging gaat over het opslaan en vasthouden van water."}}, {"text": "Wat is de hoofdboodschap van deze tekst?", "type": "Hoofdgedachte", "options": ["Nederland heeft nooit last van droogte gehad.", "Droogte is alleen een probleem in andere landen.", "Droogte is een toenemend probleem waarvoor Nederland zich structureel moet aanpassen.", "Boeren moeten stoppen met irrigeren."], "correct": 2, "highlight": "Nederland zich structureel moet aanpassen aan een droger klimaat", "feedback": {"ok": "Prima! Structurele aanpassing aan droogte is de kernboodschap.", "nee": "Niet correct. De tekst benadrukt dat Nederland zich structureel moet aanpassen aan een droger klimaat."}}]}, {"topic": "Cultuur", "title": "Nederlandse musea: wereldklasse in een kleine ruimte", "paragraphs": ["Nederland heeft meer musea per inwoner dan welk land ter wereld ook. Van het wereldberoemde Rijksmuseum in Amsterdam tot kleine streekmusea in dorpen en steden: er is voor elk wat wils. De grote steden trekken miljoenen bezoekers per jaar met topstukken van schilders als Rembrandt, Vermeer en Van Gogh.", "Naast kunstmusea heeft Nederland ook wetenschappelijke en technische musea die populair zijn bij families en scholieren. Het Nemo Science Museum in Amsterdam trekt jaarlijks meer dan zeshonderdduizend bezoekers. Musea als Naturalis in Leiden en het Spoorwegmuseum in Utrecht combineren educatie met beleving.", "Digitalisering biedt musea nieuwe mogelijkheden. Steeds meer musea bieden virtuele rondleidingen en online collecties aan, zodat mensen van over de hele wereld de werken kunnen bekijken zonder naar Nederland te reizen. Toch zeggen museumexperts dat de digitale ervaring nooit het echte bezoek kan vervangen.", "Musea spelen ook een rol in de lokale gemeenschap. Ze organiseren tentoonstellingen over actuele thema's, bieden educatieve programma's aan voor scholen en werken samen met lokale kunstenaars. Zo zijn musea niet alleen plekken om het verleden te bewaren, maar ook om na te denken over de toekomst."], "questions": [{"text": "Wat is bijzonder aan Nederland op het gebied van musea?", "type": "Detail", "options": ["Nederland heeft de grootste musea ter wereld.", "Alle musea zijn gratis toegankelijk in Nederland.", "Nederland heeft de oudste musea ter wereld.", "Nederland heeft meer musea per inwoner dan welk land ook."], "correct": 3, "highlight": "Nederland heeft meer musea per inwoner dan welk land ter wereld ook", "feedback": {"ok": "Goed! Meer musea per inwoner dan welk land ook.", "nee": "Niet juist. Alinea 1: meer musea per inwoner dan welk land ter wereld ook."}}, {"text": "Hoeveel bezoekers trekt het Nemo Science Museum per jaar?", "type": "Detail", "options": ["Meer dan een miljoen", "Meer dan twee miljoen", "Meer dan zeshonderdduizend", "Meer dan vierhonderdduizend"], "correct": 2, "highlight": "Het Nemo Science Museum in Amsterdam trekt jaarlijks meer dan zeshonderdduizend bezoekers", "feedback": {"ok": "Correct! Meer dan zeshonderdduizend bezoekers per jaar.", "nee": "Niet correct. Alinea 2: meer dan zeshonderdduizend bezoekers per jaar."}}, {"text": "Wat zeggen museumexperts over digitale rondleidingen?", "type": "Detail", "options": ["Digitale rondleidingen zijn beter dan een echt bezoek.", "Digitale rondleidingen zijn te duur om te maken.", "De digitale ervaring kan het echte bezoek nooit vervangen.", "Alle musea moeten stoppen met digitale rondleidingen."], "correct": 2, "highlight": "de digitale ervaring nooit het echte bezoek kan vervangen", "feedback": {"ok": "Juist! Experts zeggen dat digitaal het echte bezoek niet vervangt.", "nee": "Niet juist. Alinea 3: de digitale ervaring kan het echte bezoek niet vervangen."}}, {"text": "Wat betekent 'digitalisering' (alinea 3)?", "type": "Woordbetekenis", "options": ["Het afbreken van oude gebouwen", "Het sluiten van musea voor renovatie", "Het omzetten van informatie naar digitale vormen en het gebruik van digitale technologie", "Het inhuren van meer museummedewerkers"], "correct": 2, "highlight": "Digitalisering biedt musea nieuwe mogelijkheden", "feedback": {"ok": "Goed! Digitalisering = het gebruik van digitale technologie en het omzetten van informatie.", "nee": "Niet juist. Digitalisering verwijst naar het gebruik van digitale technologie en het omzetten van analoge informatie."}}, {"text": "Hoe spelen musea een rol in de lokale gemeenschap?", "type": "Inferentie", "options": ["Door alleen internationale kunstenaars uit te nodigen.", "Door tentoonstelling en educatie te combineren en samen te werken met lokale kunstenaars.", "Door hun deuren te sluiten voor scholen.", "Door alleen topstukken te bewaren en niets te organiseren."], "correct": 1, "highlight": "Ze organiseren tentoonstellingen over actuele thema's, bieden educatieve programma's aan voor scholen en werken samen met lokale kunstenaars", "feedback": {"ok": "Prima! Tentoonstellingen, educatie en samenwerking met lokale kunstenaars.", "nee": "Niet correct. Alinea 4: tentoonstellingen, educatieve programma's en samenwerking met lokale kunstenaars."}}]}, {"topic": "Financiën", "title": "Sparen of beleggen: wat is slimmer?", "paragraphs": ["Veel Nederlanders bewaren hun geld op een spaarrekening bij de bank. Dat voelt veilig: het geld staat er altijd, je kunt het makkelijk opnemen en het depositogarantiestelsel beschermt spaartegoeden tot honderdduizend euro per persoon per bank. Maar de rente op spaarrekeningen is de afgelopen jaren laag geweest, waardoor spaarders nauwelijks rendement maakten.", "Beleggen is een alternatief dat de afgelopen jaren aan populariteit heeft gewonnen. Door te beleggen in aandelen, obligaties of fondsen kan je op de lange termijn meer rendement behalen dan met sparen. Steeds meer Nederlanders, ook jongeren, beginnen met beleggen via apps die het toegankelijk maken.", "Maar beleggen brengt ook risico's met zich mee. De waarde van beleggingen kan dalen, soms fors. Wie zijn geld op korte termijn nodig heeft, kan een slecht moment treffen. Experts adviseren dan ook om alleen geld te beleggen dat je langere tijd kunt missen, en te beginnen met kleine bedragen.", "Voor de meeste mensen is een combinatie van sparen en beleggen het verstandigst. Een buffer op de spaarrekening voor onverwachte uitgaven, en eventueel extra geld beleggen voor de lange termijn. Financieel adviseurs benadrukken dat goede spreiding en een lange tijdshorizon de risico's van beleggen sterk verminderen."], "questions": [{"text": "Hoeveel spaargeld beschermt het depositogarantiestelsel per persoon per bank?", "type": "Detail", "options": ["Tot vijftigduizend euro", "Tot tweehonderdduizend euro", "Tot honderdduizend euro", "Tot vijfentwintigduizend euro"], "correct": 2, "highlight": "het depositogarantiestelsel beschermt spaartegoeden tot honderdduizend euro per persoon per bank", "feedback": {"ok": "Goed! Het depositogarantiestelsel beschermt tot honderdduizend euro.", "nee": "Niet juist. Alinea 1: bescherming tot honderdduizend euro per persoon per bank."}}, {"text": "Waarom is beleggen populairder geworden?", "type": "Detail", "options": ["Omdat spaarrekeningen niet meer bestaan.", "Omdat beleggen altijd winstgevend is.", "Omdat de overheid dit verplicht stelt.", "Omdat men op de lange termijn meer rendement kan behalen dan met sparen."], "correct": 3, "highlight": "op de lange termijn meer rendement behalen dan met sparen", "feedback": {"ok": "Correct! Op de lange termijn meer rendement dan sparen.", "nee": "Niet correct. Alinea 2: meer rendement op de lange termijn."}}, {"text": "Wat is een risico van beleggen?", "type": "Detail", "options": ["Je kunt het geld niet meer opnemen.", "De bank kan failliet gaan.", "De waarde van beleggingen kan dalen.", "Je betaalt altijd meer belasting."], "correct": 2, "highlight": "De waarde van beleggingen kan dalen, soms fors", "feedback": {"ok": "Juist! Beleggingen kunnen in waarde dalen.", "nee": "Niet juist. Alinea 3: de waarde van beleggingen kan dalen."}}, {"text": "Wat betekent 'tijdshorizon' (alinea 4)?", "type": "Woordbetekenis", "options": ["De maximale winst die je kunt maken", "Het maximum bedrag dat je mag beleggen", "De periode waarvoor je belegt of spaart", "De kosten van een beleggingsrekening"], "correct": 2, "highlight": "een lange tijdshorizon de risico's van beleggen sterk verminderen", "feedback": {"ok": "Goed! Tijdshorizon = de periode waarvoor je belegt.", "nee": "Niet juist. Tijdshorizon verwijst naar de periode waarvoor je belegt of spaart."}}, {"text": "Wat is het advies voor de meeste mensen?", "type": "Hoofdgedachte", "options": ["Alles beleggen voor het hoogste rendement.", "Alleen sparen en nooit beleggen.", "Een combinatie van sparen en beleggen.", "Alle spaargeld bewaren in contant geld."], "correct": 2, "highlight": "een combinatie van sparen en beleggen het verstandigst", "feedback": {"ok": "Prima! Een combinatie van sparen en beleggen is het verstandigst.", "nee": "Niet correct. Alinea 4: voor de meeste mensen is een combinatie het verstandigst."}}]}, {"topic": "Architectuur", "title": "Nederlandse architectuur: van grachtenpand tot wolkenkrabber", "paragraphs": ["De Nederlandse architectuur is de afgelopen eeuwen sterk veranderd. De smalle grachtenpanden in Amsterdam, met hun gevels en grote ramen, dateren uit de Gouden Eeuw van de zeventiende eeuw. Ze werden gebouwd op de smalle kavels langs de grachten, waardoor ze hoog en smal zijn. De gevels zijn vaak versierd met trapgevels, halsgevel of klokgevels.", "In de twintigste eeuw moderniseerde de Nederlandse architectuur ingrijpend. Nederland werd een internationaal begrip dankzij stromingen als De Stijl, met architecten als Gerrit Rietveld. Het Rietveld Schröderhuis in Utrecht is een wereldberoemd voorbeeld van modernistische architectuur en staat op de UNESCO-werelderfgoedlijst.", "Tegenwoordig staat Nederland bekend als een laboratorium voor innovatieve architectuur. Steden als Rotterdam, dat grotendeels opnieuw werd opgebouwd na de Tweede Wereldoorlog, tonen spectaculaire gebouwen zoals de Markthal en de kubuswoningen. Architectenbureaus zoals Rem Koolhaas' OMA hebben wereldwijde invloed.", "Duurzaamheid speelt een steeds grotere rol in de hedendaagse Nederlandse architectuur. Nieuwe gebouwen worden ontworpen met zonnepanelen, groene daken en energie-efficiënte materialen. Er zijn ook projecten waarbij oude fabrieken of kantoren worden omgebouwd tot woningen, om zo duurzaam gebruik te maken van bestaande structuren."], "questions": [{"text": "Waarom zijn grachtenpanden in Amsterdam hoog en smal?", "type": "Detail", "options": ["Omdat het goedkoper was om hoge gebouwen te bouwen.", "Omdat brede gebouwen verboden waren.", "Omdat ze gebouwd werden op smalle kavels langs de grachten.", "Omdat de bouwhoogte door de overheid werd bepaald."], "correct": 2, "highlight": "Ze werden gebouwd op de smalle kavels langs de grachten, waardoor ze hoog en smal zijn", "feedback": {"ok": "Goed! Smalle kavels langs de grachten bepaalden de vorm.", "nee": "Niet juist. Alinea 1: de smalle kavels langs de grachten."}}, {"text": "Op welke lijst staat het Rietveld Schröderhuis?", "type": "Detail", "options": ["De lijst van nationale monumenten van Utrecht.", "De Forbes-lijst van duurste gebouwen.", "De lijst van de duurste architecten ter wereld.", "De UNESCO-werelderfgoedlijst."], "correct": 3, "highlight": "staat op de UNESCO-werelderfgoedlijst", "feedback": {"ok": "Correct! Het Rietveld Schröderhuis staat op de UNESCO-werelderfgoedlijst.", "nee": "Niet correct. Alinea 2: het staat op de UNESCO-werelderfgoedlijst."}}, {"text": "Waarvoor staat Rotterdam bekend op het gebied van architectuur?", "type": "Detail", "options": ["Voor zijn historische grachtenpanden.", "Voor zijn gemiddelde architectuur.", "Voor zijn traditionele dorpskerken.", "Voor spectaculaire innovatieve gebouwen zoals de Markthal."], "correct": 3, "highlight": "tonen spectaculaire gebouwen zoals de Markthal en de kubuswoningen", "feedback": {"ok": "Juist! Rotterdam heeft spectaculaire innovatieve gebouwen.", "nee": "Niet juist. Alinea 3: Rotterdam heeft spectaculaire gebouwen zoals de Markthal."}}, {"text": "Wat betekent 'energie-efficiënt' (alinea 4)?", "type": "Woordbetekenis", "options": ["Duurder om te verwarmen", "Zo weinig mogelijk energie gebruiken voor hetzelfde resultaat", "Powered by solar energy", "Gemakkelijk te verwarmen in de winter"], "correct": 1, "highlight": "energie-efficiënte materialen", "feedback": {"ok": "Goed! Energie-efficiënt = zo min mogelijk energie gebruiken voor hetzelfde resultaat.", "nee": "Niet juist. Energie-efficiënt betekent zo weinig mogelijk energie gebruiken voor hetzelfde resultaat."}}, {"text": "Hoe wordt duurzaamheid toegepast in nieuwe gebouwen?", "type": "Inferentie", "options": ["Door alleen traditionele materialen te gebruiken.", "Door gebouwen kleiner te maken.", "Door gebruik van zonnepanelen, groene daken en hergebruik van bestaande structuren.", "Door gebouwen in de natuur te plaatsen."], "correct": 2, "highlight": "Nieuwe gebouwen worden ontworpen met zonnepanelen, groene daken en energie-efficiënte materialen", "feedback": {"ok": "Prima! Zonnepanelen, groene daken en hergebruik van bestaande structuren.", "nee": "Niet correct. Alinea 4: zonnepanelen, groene daken en hergebruik van bestaande structuren."}}]},
  {"topic":"Muziek","title":"Nederlandse muziek: meer dan alleen Nederlandstalig","paragraphs":["Nederland heeft een rijke muziektraditie die veel verder gaat dan alleen Nederlandstalige popmuziek. In de klassieke muziek staat het Concertgebouworkest in Amsterdam wereldwijd bekend als een van de beste orkesten ter wereld. Het Concertgebouw, gebouwd in 1888, trekt jaarlijks ruim achthonderdduizend bezoekers.","In de popmuziek heeft Nederland internationaal succes geboekt met artiesten als Tiësto, Afrojack en Martin Garrix, die de elektronische dansmuziek naar een wereldwijd publiek hebben gebracht. De stad Amsterdam geldt als een van de centra van de internationale dj-cultuur. Jaarlijks vindt het Amsterdam Dance Event plaats, een van de grootste elektronische muziekfestivals ter wereld.","Nederlandstalige muziek beleeft de laatste jaren een opmerkelijke renaissance. Artiesten als Snelle, Maan en Nielson scoren grote hits met liedjes in het Nederlands. Jongeren die vroeger liever Engelstalige muziek luisterden, omarmen nu steeds vaker muziek in hun eigen taal.","Naast popmuziek is er in Nederland ook een levendige folktraditie. Volksmuziek uit provincies als Zeeland, Friesland en Limburg heeft eigen kenmerken en instrumenten. Friese muziek kent bijvoorbeeld een sterke koortraditie, terwijl Limburgse muziek sterk beïnvloed is door de buurlanden België en Duitsland."],"questions":[{"text":"Hoeveel bezoekers trekt het Concertgebouw jaarlijks?","type":"Detail","options":["Ruim vierhonderdduizend","Ruim zeshonderdduizend","Ruim tweehonderdduizend","Ruim achthonderdduizend"],"correct":3,"highlight":"trekt jaarlijks ruim achthonderdduizend bezoekers","feedback":{"ok":"Goed! Ruim achthonderdduizend bezoekers per jaar.","nee":"Niet juist. Alinea 1: ruim achthonderdduizend bezoekers per jaar."}},{"text":"Waarvoor staat Amsterdam bekend in de muziekwereld?","type":"Detail","options":["Als centrum van klassieke muziek in Europa.","Als centrum van de internationale dj-cultuur.","Als birthplace van Nederlandstalige pop.","Als centrum van volksmuziek."],"correct":1,"highlight":"De stad Amsterdam geldt als een van de centra van de internationale dj-cultuur","feedback":{"ok":"Correct! Amsterdam is een centrum van de internationale dj-cultuur.","nee":"Niet correct. Alinea 2: Amsterdam staat bekend als centrum van de internationale dj-cultuur."}},{"text":"Wat is opmerkelijk aan de renaissance van Nederlandstalige muziek?","type":"Detail","options":["Jongeren luisteren minder muziek dan vroeger.","Nederlandstalige muziek wordt alleen in het buitenland populair.","Jongeren omarmen steeds vaker muziek in hun eigen taal.","Engelstalige muziek is verboden op radio."],"correct":2,"highlight":"Jongeren die vroeger liever Engelstalige muziek luisterden, omarmen nu steeds vaker muziek in hun eigen taal","feedback":{"ok":"Juist! Jongeren kiezen vaker voor Nederlandstalige muziek.","nee":"Niet juist. Alinea 3: jongeren omarmen nu steeds vaker muziek in hun eigen taal."}},{"text":"Wat betekent 'renaissance' (alinea 3)?","type":"Woordbetekenis","options":["Een langzame achteruitgang","Een nieuw begin of hergeboorte van iets","Een muziekgenre uit Italië","Een festival voor klassieke muziek"],"correct":1,"highlight":"beleeft de laatste jaren een opmerkelijke renaissance","feedback":{"ok":"Goed! Renaissance betekent een herleving of nieuw begin.","nee":"Niet juist. Renaissance betekent een herleving of nieuw begin van iets."}},{"text":"Wat is kenmerkend voor Limburgse muziek?","type":"Inferentie","options":["Een sterke koortraditie.","Eigen unieke instrumenten die nergens anders voorkomen.","Invloed van de buurlanden België en Duitsland.","Volledig gebaseerd op Nederlandstalige teksten."],"correct":2,"highlight":"Limburgse muziek sterk beïnvloed is door de buurlanden België en Duitsland","feedback":{"ok":"Prima! Limburgse muziek is sterk beïnvloed door België en Duitsland.","nee":"Niet correct. Alinea 4: Limburgse muziek is beïnvloed door België en Duitsland."}}]},{"topic":"Voedsel","title":"Kaas: een Nederlandse trots","paragraphs":["Nederland is een van de grootste kaasproducenten en kaasexporteurs ter wereld. Bekende Nederlandse kaassoorten zoals Gouda, Edam en Leerdammer worden wereldwijd gegeten. De kaasmarkt in Alkmaar, een van de laatste authentieke kaasmarkten in Nederland, trekt elk jaar tienduizenden toeristen.","De productie van kaas begint bij de koe. Nederland heeft een hoge veedichtheid: er leven meer dan vier miljoen koeien in het land. De melk die zij produceren, wordt verwerkt door zuivelfabrieken die verspreid over het land liggen. Het hele proces, van melken tot kaasproductie, is in Nederland sterk geautomatiseerd.","Kaas speelt een belangrijke rol in de Nederlandse eetcultuur. Nederlanders eten gemiddeld meer dan veertien kilo kaas per jaar per persoon, wat ver boven het Europees gemiddelde ligt. Kaas wordt gegeten als broodbeleg, als snack, verwerkt in warme gerechten of geserveerd op een kaasplank bij de borrel.","De kaassector staat echter voor uitdagingen. Milieucritici wijzen op de hoge uitstoot van broeikasgassen door de veeteelt. Er is ook druk om het waterverbruik en de stikstofuitstoot te verminderen. Sommige kaasmakers experimenteren met plantaardige alternatieven, maar traditionele kaasliefhebbers zijn niet snel overtuigd."],"questions":[{"text":"Hoeveel koeien leven er in Nederland?","type":"Detail","options":["Meer dan drie miljoen","Meer dan vijf miljoen","Meer dan twee miljoen","Meer dan vier miljoen"],"correct":3,"highlight":"er leven meer dan vier miljoen koeien in het land","feedback":{"ok":"Goed! Meer dan vier miljoen koeien.","nee":"Niet juist. Alinea 2: meer dan vier miljoen koeien."}},{"text":"Hoeveel kaas eten Nederlanders gemiddeld per jaar?","type":"Detail","options":["Meer dan tien kilo","Meer dan twintig kilo","Meer dan veertien kilo","Meer dan acht kilo"],"correct":2,"highlight":"Nederlanders eten gemiddeld meer dan veertien kilo kaas per jaar per persoon","feedback":{"ok":"Correct! Meer dan veertien kilo per persoon per jaar.","nee":"Niet correct. Alinea 3: meer dan veertien kilo per persoon per jaar."}},{"text":"Welke uitdaging staat de kaassector te wachten?","type":"Detail","options":["Te weinig koeien voor de productie.","Hoge uitstoot van broeikasgassen door de veeteelt.","Gebrek aan interesse van consumenten.","Te veel concurrentie uit het buitenland."],"correct":1,"highlight":"de hoge uitstoot van broeikasgassen door de veeteelt","feedback":{"ok":"Juist! Hoge uitstoot van broeikasgassen is een grote uitdaging.","nee":"Niet juist. Alinea 4: de hoge uitstoot van broeikasgassen door de veeteelt."}},{"text":"Wat betekent 'veedichtheid' (alinea 2)?","type":"Woordbetekenis","options":["Het gewicht van de koeien in een gebied","De kwaliteit van het veevoer","Het aantal dieren per oppervlakte-eenheid","De afstand tussen boerderijen"],"correct":2,"highlight":"Nederland heeft een hoge veedichtheid","feedback":{"ok":"Goed! Veedichtheid = het aantal dieren per oppervlakte-eenheid.","nee":"Niet juist. Veedichtheid verwijst naar het aantal dieren per oppervlakte-eenheid."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederland moet stoppen met kaasproductie.","Kaas is het populairste voedsel in Europa.","Kaas is een belangrijke sector in Nederland, maar staat voor milieu-uitdagingen.","Toeristen komen alleen naar Nederland voor kaas."],"correct":2,"highlight":"De kaassector staat echter voor uitdagingen","feedback":{"ok":"Prima! Kaas is belangrijk voor Nederland maar staat voor uitdagingen.","nee":"Niet correct. De tekst beschrijft zowel het belang als de uitdagingen van de kaassector."}}]},{"topic":"Politiek","title":"De Nederlandse democratie: hoe werkt het?","paragraphs":["Nederland is een constitutionele monarchie met een parlementaire democratie. De koning of koningin heeft een ceremoniële rol, terwijl de politieke macht bij de gekozen volksvertegenwoordigers ligt. Het parlement, de Staten-Generaal, bestaat uit twee kamers: de Tweede Kamer en de Eerste Kamer.","De Tweede Kamer heeft 150 zetels en wordt direct gekozen door de Nederlandse bevolking via evenredige vertegenwoordiging. Dit betekent dat partijen zetels krijgen in verhouding tot het percentage stemmen dat ze behalen. Hierdoor zijn er in Nederland altijd meerdere partijen in de Tweede Kamer, soms wel vijftien of meer.","Omdat geen enkele partij ooit de meerderheid haalt, moeten partijen samenwerken om een coalitie te vormen. Dit proces, de formatie, kan weken of zelfs maanden duren. Een formateur of informateur begeleidt de onderhandelingen. Uiteindelijk presenteert de coalitie een regeerakkoord met de plannen voor de komende jaren.","De Eerste Kamer, ook wel de Senaat of de 'chambre de réflexion' genoemd, bestaat uit 75 leden die indirect worden gekozen door de provinciale staten. De Eerste Kamer kan wetten goedkeuren of verwerpen, maar kan ze niet zelf wijzigen. Dit systeem zorgt voor een extra controle op de wetgeving."],"questions":[{"text":"Hoeveel zetels heeft de Tweede Kamer?","type":"Detail","options":["125 zetels","100 zetels","175 zetels","150 zetels"],"correct":3,"highlight":"De Tweede Kamer heeft 150 zetels","feedback":{"ok":"Goed! De Tweede Kamer heeft 150 zetels.","nee":"Niet juist. Alinea 2: de Tweede Kamer heeft 150 zetels."}},{"text":"Wat betekent evenredige vertegenwoordiging?","type":"Woordbetekenis","options":["Alle partijen krijgen evenveel zetels.","Alleen grote partijen krijgen zetels.","Partijen krijgen zetels in verhouding tot hun stempercentage.","De koning verdeelt de zetels eerlijk."],"correct":2,"highlight":"partijen zetels krijgen in verhouding tot het percentage stemmen dat ze behalen","feedback":{"ok":"Correct! Zetels worden verdeeld naar stempercentage.","nee":"Niet correct. Alinea 2: zetels worden verdeeld in verhouding tot het stempercentage."}},{"text":"Waarom duurt de formatie soms lang?","type":"Inferentie","options":["Omdat de koning het regeerakkoord moet goedkeuren.","Omdat partijen moeten samenwerken om een meerderheidscoalitie te vormen.","Omdat verkiezingen opnieuw gehouden moeten worden.","Omdat de Eerste Kamer het formatieteam moet aanwijzen."],"correct":1,"highlight":"moeten partijen samenwerken om een coalitie te vormen. Dit proces, de formatie, kan weken of zelfs maanden duren","feedback":{"ok":"Juist! Samenwerken voor een coalitie kost tijd.","nee":"Niet juist. Alinea 3: partijen moeten onderhandelen over een coalitie."}},{"text":"Wat kan de Eerste Kamer NIET doen?","type":"Detail","options":["Wetten goedkeuren.","Wetten verwerpen.","Wetten zelf wijzigen.","Wetsvoorstellen beoordelen."],"correct":2,"highlight":"De Eerste Kamer kan wetten goedkeuren of verwerpen, maar kan ze niet zelf wijzigen","feedback":{"ok":"Goed! De Eerste Kamer kan wetten niet zelf wijzigen.","nee":"Niet juist. Alinea 4: de Eerste Kamer kan wetten niet zelf wijzigen."}},{"text":"Welke rol heeft de koning in de Nederlandse democratie?","type":"Detail","options":["De koning beslist over nieuwe wetten.","De koning kiest de ministers.","De koning heeft een ceremoniële rol.","De koning leidt de formatie."],"correct":2,"highlight":"De koning of koningin heeft een ceremoniële rol","feedback":{"ok":"Prima! De rol van de koning is ceremonieel.","nee":"Niet correct. Alinea 1: de koning heeft een ceremoniële rol."}}]},{"topic":"Technologie","title":"Kunstmatige intelligentie in het dagelijks leven","paragraphs":["Kunstmatige intelligentie, ook wel AI genoemd, is niet meer weg te denken uit het dagelijks leven. Van de aanbevelingen op streamingdiensten tot de navigatieapp op je telefoon: AI werkt overal op de achtergrond. Veel mensen gebruiken AI zonder het te beseffen, omdat de technologie naadloos in bestaande producten is geïntegreerd.","In de gezondheidszorg biedt AI grote kansen. Computerprogramma's kunnen medische scans analyseren en afwijkingen opsporen die voor het menselijk oog moeilijk zichtbaar zijn. Ook bij het voorspellen van ziektes en het personaliseren van behandelingen speelt AI een steeds grotere rol. Artsen gebruiken AI als hulpmiddel, maar de uiteindelijke beslissing blijft bij de dokter.","Op de arbeidsmarkt roept AI gemengde gevoelens op. Sommige banen verdwijnen doordat machines taken overnemen die vroeger mensen deden. Maar AI creëert ook nieuwe banen: er is grote vraag naar mensen die AI-systemen kunnen ontwikkelen, beheren en controleren. Experts verwachten dat de komende decennia grote verschuivingen op de arbeidsmarkt zullen plaatsvinden.","Er zijn ook zorgen over de risico's van AI. Algoritmes kunnen vooroordelen bevatten als ze getraind worden op ongelijke data. Deepfakes — nep video's of foto's gemaakt met AI — kunnen worden gebruikt om mensen te misleiden. Overheden werken aan regelgeving om de ontwikkeling van AI in goede banen te leiden."],"questions":[{"text":"Hoe gebruikt AI op aanbevelingen van streamingdiensten?","type":"Inferentie","options":["AI schrijft de films en series zelf.","AI bepaalt de abonnementsprijs.","AI werkt op de achtergrond om aanbevelingen te doen.","AI vertaalt de films naar het Nederlands."],"correct":2,"highlight":"AI werkt overal op de achtergrond","feedback":{"ok":"Goed! AI werkt op de achtergrond bij aanbevelingen.","nee":"Niet juist. Alinea 1: AI werkt op de achtergrond bij aanbevelingen."}},{"text":"Hoe wordt AI gebruikt in de gezondheidszorg?","type":"Detail","options":["AI vervangt artsen volledig.","AI schrijft recepten uit zonder tussenkomst van artsen.","AI analyseert medische scans en helpt ziektes te voorspellen.","AI bepaalt welke patiënten behandeld worden."],"correct":2,"highlight":"Computerprogramma's kunnen medische scans analyseren en afwijkingen opsporen","feedback":{"ok":"Correct! AI analyseert scans en helpt bij het voorspellen van ziektes.","nee":"Niet correct. Alinea 2: AI analyseert scans en helpt ziektes voorspellen."}},{"text":"Wat voor nieuwe banen creëert AI?","type":"Detail","options":["Banen in de traditionele industrie.","Banen voor mensen die AI-systemen ontwikkelen en beheren.","Banen als verpleegkundige en leraar.","Banen in de landbouw."],"correct":1,"highlight":"er is grote vraag naar mensen die AI-systemen kunnen ontwikkelen, beheren en controleren","feedback":{"ok":"Juist! Er is vraag naar mensen die AI ontwikkelen en beheren.","nee":"Niet juist. Alinea 3: er is vraag naar mensen die AI-systemen ontwikkelen en beheren."}},{"text":"Wat zijn deepfakes?","type":"Woordbetekenis","options":["Nep accounts op sociale media","Foute informatie op internet","Nep video's of foto's gemaakt met AI","Virussen die computersystemen aanvallen"],"correct":2,"highlight":"Deepfakes — nep video's of foto's gemaakt met AI","feedback":{"ok":"Goed! Deepfakes zijn nep video's of foto's gemaakt met AI.","nee":"Niet juist. Alinea 4: deepfakes zijn nep video's of foto's gemaakt met AI."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["AI is gevaarlijk en moet verboden worden.","AI heeft alleen voordelen voor de samenleving.","AI biedt kansen maar brengt ook risico's met zich mee.","AI vervangt alle menselijke banen."],"correct":2,"highlight":"Er zijn ook zorgen over de risico's van AI","feedback":{"ok":"Prima! AI biedt kansen maar brengt ook risico's met zich mee.","nee":"Niet correct. De tekst bespreekt zowel kansen als risico's van AI."}}]},{"topic":"Geografie","title":"De Waddeneilanden: parels van de Noordzee","paragraphs":["De Waddeneilanden zijn een rij van vijf bewoonde eilanden voor de kust van Noord-Holland en Friesland: Texel, Vlieland, Terschelling, Ameland en Schiermonnikoog. Ze maken deel uit van het Waddengebied, dat in 2009 op de UNESCO-werelderfgoedlijst werd geplaatst vanwege zijn unieke natuur.","Het Wad, de ondiepe zee tussen de eilanden en de vaste wal, droogt tweemaal per dag gedeeltelijk droog bij laagwater. Dit fenomeen, het getij, maakt het mogelijk om te wadlopen: te voet door het slik en zand van het wad trekken bij laagwater. Wadlopen is een populaire activiteit die alleen onder begeleiding van een gids mag plaatsvinden.","De eilanden zijn een paradijs voor vogels en zeehonden. Miljoenen vogels gebruiken het Waddengebied als rustplaats tijdens hun trek van en naar noordelijkere broedgebieden. Zeehonden leggen op de zandplaten en zijn een geliefde attractie voor toeristen. Het gebied is dan ook aangewezen als beschermd natuurgebied.","Toerisme is voor de eilanden een belangrijke bron van inkomsten, maar ook een uitdaging. In de zomer stromen de eilanden vol met bezoekers, wat druk legt op de natuur en de sfeer voor bewoners. Sommige eilanden beperken het aantal dagtoeristen om de leefbaarheid en de natuur te beschermen."],"questions":[{"text":"Hoeveel bewoonde Waddeneilanden heeft Nederland?","type":"Detail","options":["Vier","Zeven","Drie","Vijf"],"correct":3,"highlight":"een rij van vijf bewoonde eilanden","feedback":{"ok":"Goed! Nederland heeft vijf bewoonde Waddeneilanden.","nee":"Niet juist. Alinea 1: er zijn vijf bewoonde Waddeneilanden."}},{"text":"Wanneer werd het Waddengebied op de UNESCO-lijst geplaatst?","type":"Detail","options":["In 2005","In 2015","In 2000","In 2009"],"correct":3,"highlight":"in 2009 op de UNESCO-werelderfgoedlijst werd geplaatst","feedback":{"ok":"Correct! In 2009 werd het op de UNESCO-lijst geplaatst.","nee":"Niet correct. Alinea 1: in 2009."}},{"text":"Wanneer is wadlopen mogelijk?","type":"Detail","options":["Alleen bij vloed.","Het hele jaar door, ongeacht het getij.","Alleen bij zonsondergang.","Bij laagwater, als het wad gedeeltelijk droogvalt."],"correct":3,"highlight":"te voet door het slik en zand van het wad trekken bij laagwater","feedback":{"ok":"Juist! Wadlopen is mogelijk bij laagwater.","nee":"Niet juist. Alinea 2: wadlopen is mogelijk bij laagwater."}},{"text":"Wat betekent 'broedgebied' (alinea 3)?","type":"Woordbetekenis","options":["Een gebied waar dieren overwinteren","Een gebied waar dieren voedsel zoeken","Een gebied waar vogels of dieren jongen grootbrengen","Een beschermd bosgebied"],"correct":2,"highlight":"broedgebieden","feedback":{"ok":"Goed! Een broedgebied is waar vogels of dieren jongen grootbrengen.","nee":"Niet juist. Een broedgebied is een gebied waar dieren zich voortplanten en jongen grootbrengen."}},{"text":"Waarom beperken sommige eilanden het aantal dagtoeristen?","type":"Inferentie","options":["Omdat er te weinig hotels zijn.","Omdat dagtouristen te weinig geld uitgeven.","Om de leefbaarheid en de natuur te beschermen.","Omdat de veerboten te weinig capaciteit hebben."],"correct":2,"highlight":"Sommige eilanden beperken het aantal dagtoeristen om de leefbaarheid en de natuur te beschermen","feedback":{"ok":"Prima! Om de leefbaarheid en natuur te beschermen.","nee":"Niet correct. Alinea 4: om de leefbaarheid en de natuur te beschermen."}}]},{"topic":"Ondernemen","title":"Startups in Nederland: een bloeiend ecosysteem","paragraphs":["Nederland heeft de afgelopen decennia een sterk ecosysteem voor startups opgebouwd. Amsterdam staat in Europese ranglijsten consequent in de top vijf van beste steden voor startende ondernemers. De aanwezigheid van grote internationale bedrijven, goede infrastructuur en een hoog opgeleid Engelstalig personeelsbestand trekken jonge bedrijven aan.","De Nederlandse overheid stimuleert ondernemerschap actief. Er zijn fiscale voordelen voor investeerders in startups en er bestaan subsidies voor innovatieve bedrijven. De WBSO, een fiscale regeling voor onderzoek en ontwikkeling, helpt technologiebedrijven om hun kosten te drukken. Incubators en accelerators begeleiden startende ondernemers met advies en netwerk.","Bekende Nederlandse successen uit de startupwereld zijn onder meer Booking.com, Adyen en Coolblue. Deze bedrijven begonnen klein maar groeiden uit tot internationale spelers. Booking.com, oorspronkelijk opgericht in Amsterdam, is inmiddels een van de grootste reisplatforms ter wereld.","Toch is ondernemen niet zonder risico. Veel startups mislukken binnen de eerste vijf jaar. Gebrek aan financiering, te sterke concurrentie of een product dat de markt niet nodig blijkt te hebben, zijn veelgenoemde oorzaken. Succesvolle ondernemers benadrukken het belang van flexibiliteit, het leren van fouten en het opbouwen van een sterk netwerk."],"questions":[{"text":"Waar staat Amsterdam consequent in op Europese ranglijsten?","type":"Detail","options":["In de top tien van duurzaamste steden.","In de top vijf van beste steden voor startende ondernemers.","In de top drie van goedkoopste steden voor bedrijven.","In de top vijf van steden met de meeste grote bedrijven."],"correct":1,"highlight":"Amsterdam staat in Europese ranglijsten consequent in de top vijf van beste steden voor startende ondernemers","feedback":{"ok":"Goed! Amsterdam staat in de top vijf van beste steden voor startende ondernemers.","nee":"Niet juist. Alinea 1: Amsterdam staat consequent in de top vijf."}},{"text":"Waarvoor dient de WBSO-regeling?","type":"Detail","options":["Om startups te verbinden met investeerders.","Om werknemers bij te scholen.","Om technologiebedrijven te helpen hun kosten te drukken.","Om de export van Nederlandse producten te stimuleren."],"correct":2,"highlight":"De WBSO, een fiscale regeling voor onderzoek en ontwikkeling, helpt technologiebedrijven om hun kosten te drukken","feedback":{"ok":"Correct! De WBSO helpt technologiebedrijven hun kosten te drukken.","nee":"Niet correct. Alinea 2: de WBSO helpt technologiebedrijven kosten te drukken."}},{"text":"Waar is Booking.com oorspronkelijk opgericht?","type":"Detail","options":["In Rotterdam","In Utrecht","In Amsterdam","In Den Haag"],"correct":2,"highlight":"Booking.com, oorspronkelijk opgericht in Amsterdam","feedback":{"ok":"Juist! Booking.com is opgericht in Amsterdam.","nee":"Niet juist. Alinea 3: Booking.com is oorspronkelijk opgericht in Amsterdam."}},{"text":"Wat betekent 'accelerator' (alinea 2)?","type":"Woordbetekenis","options":["Een overheidsorganisatie die belastingen controleert","Een programma dat startende bedrijven begeleidt met advies en netwerk","Een investeringsfonds voor grote bedrijven","Een softwareprogramma voor financiële administratie"],"correct":1,"highlight":"Incubators en accelerators begeleiden startende ondernemers met advies en netwerk","feedback":{"ok":"Goed! Een accelerator begeleidt startende bedrijven met advies en netwerk.","nee":"Niet juist. Een accelerator is een programma dat startende bedrijven begeleidt."}},{"text":"Wat benadrukken succesvolle ondernemers als sleutel tot succes?","type":"Detail","options":["Zo snel mogelijk veel geld ophalen bij investeerders.","Flexibiliteit, leren van fouten en een sterk netwerk.","Altijd vasthouden aan het oorspronkelijke plan.","Zo weinig mogelijk risico's nemen."],"correct":1,"highlight":"Succesvolle ondernemers benadrukken het belang van flexibiliteit, het leren van fouten en het opbouwen van een sterk netwerk","feedback":{"ok":"Prima! Flexibiliteit, leren van fouten en netwerk opbouwen.","nee":"Niet correct. Alinea 4: flexibiliteit, leren van fouten en een sterk netwerk."}}]},{"topic":"Gezondheid","title":"Mentale gezondheid: een groeiend aandachtspunt","paragraphs":["Mentale gezondheid staat in Nederland steeds meer op de agenda. Steeds meer mensen zoeken hulp voor psychische klachten zoals angst, depressie of burn-out. De wachttijden bij psychologen en psychiaters zijn de afgelopen jaren sterk opgelopen, wat een teken is van de groeiende vraag naar geestelijke gezondheidszorg.","Burn-out is een van de meest voorkomende klachten. Het gaat om een staat van uitputting die ontstaat door langdurige stress, vaak door werkdruk. Klachten zijn onder meer extreme vermoeidheid, concentratieproblemen en een gevoel van machteloosheid. Herstel van een burn-out duurt gemiddeld meerdere maanden.","Werkgevers beginnen het belang van mentale gezondheid te erkennen. Steeds meer bedrijven bieden hun werknemers toegang tot coaching, online therapie of een bedrijfsmaatschappelijk werker. Preventie — het voorkomen van klachten voordat ze ernstig worden — staat hoog op de agenda van HR-afdelingen.","Jongeren zijn een bijzondere risicogroep. Onderzoek toont aan dat jongeren in Nederland meer stress ervaren dan vorige generaties. Sociale media, prestatiedruk op school en onzekerheid over de toekomst zijn genoemde factoren. Scholen en gemeenten werken aan programma's om de weerbaarheid van jongeren te versterken."],"questions":[{"text":"Wat is een teken van de groeiende vraag naar geestelijke gezondheidszorg?","type":"Detail","options":["Meer psychologen worden opgeleid.","Er zijn meer ziekenhuizen gebouwd.","De wachttijden bij psychologen zijn sterk opgelopen.","Mensen praten openlijker over mentale gezondheid."],"correct":2,"highlight":"De wachttijden bij psychologen en psychiaters zijn de afgelopen jaren sterk opgelopen","feedback":{"ok":"Goed! Oplopende wachttijden zijn een teken van de groeiende vraag.","nee":"Niet juist. Alinea 1: de wachttijden zijn sterk opgelopen."}},{"text":"Wat is een burn-out?","type":"Woordbetekenis","options":["Een tijdelijke verkoudheid door stress","Een staat van uitputting door langdurige stress","Een psychische aandoening die erfelijk is","Een korte periode van vermoeidheid na sport"],"correct":1,"highlight":"een staat van uitputting die ontstaat door langdurige stress","feedback":{"ok":"Correct! Burn-out is een staat van uitputting door langdurige stress.","nee":"Niet correct. Alinea 2: burn-out is een staat van uitputting door langdurige stress."}},{"text":"Hoe reageren werkgevers op de mentale gezondheidscrisis?","type":"Detail","options":["Ze verminderen de werkdruk voor alle werknemers.","Ze ontslaan werknemers met psychische klachten.","Ze bieden toegang tot coaching, online therapie of bedrijfsmaatschappelijk werk.","Ze sturen werknemers vaker op vakantie."],"correct":2,"highlight":"Steeds meer bedrijven bieden hun werknemers toegang tot coaching, online therapie of een bedrijfsmaatschappelijk werker","feedback":{"ok":"Juist! Coaching, online therapie en bedrijfsmaatschappelijk werk.","nee":"Niet juist. Alinea 3: coaching, online therapie en bedrijfsmaatschappelijk werk."}},{"text":"Welke factoren zorgen voor stress bij jongeren?","type":"Detail","options":["Gebrek aan sport en beweging.","Te weinig slaap door laat uitgaan.","Sociale media, prestatiedruk en onzekerheid over de toekomst.","Gebrek aan vriendschappen."],"correct":2,"highlight":"Sociale media, prestatiedruk op school en onzekerheid over de toekomst zijn genoemde factoren","feedback":{"ok":"Goed! Sociale media, prestatiedruk en toekomstangst.","nee":"Niet juist. Alinea 4: sociale media, prestatiedruk en onzekerheid over de toekomst."}},{"text":"Wat is het doel van preventie in de context van mentale gezondheid?","type":"Inferentie","options":["Zo snel mogelijk medicijnen voorschrijven.","Klachten behandelen nadat ze ernstig zijn geworden.","Mensen ontmoedigen om hulp te vragen.","Klachten voorkomen voordat ze ernstig worden."],"correct":3,"highlight":"Preventie — het voorkomen van klachten voordat ze ernstig worden","feedback":{"ok":"Prima! Preventie = voorkomen dat klachten ernstig worden.","nee":"Niet correct. Alinea 3: preventie is het voorkomen van klachten voordat ze ernstig worden."}}]},{"topic":"Sport","title":"Schaatsen in Nederland: een nationale passie","paragraphs":["Schaatsen is in Nederland meer dan een sport — het is een cultureel fenomeen. Op de schaatsbaan, maar ook op bevroren sloten, meren en kanalen, scheren Nederlanders over het ijs zodra de temperatuur lang genoeg laag genoeg is. De Elfstedentocht, een tocht van bijna tweehonderd kilometer langs elf Friese steden, is het hoogtepunt van de schaatscultuur.","De laatste Elfstedentocht werd gereden in 1997. Sindsdien is het in Nederland niet meer koud genoeg geweest voor de tocht. Door de klimaatverandering worden strenge winters steeds zeldzamer. Toch blijft de verwachting voor een nieuwe Elfstedentocht elk winter opleven als de temperaturen dalen.","Op de kunstijsbaan laat Nederland ook internationaal van zich horen. Nederlandse schaatsers domineren al decennialang het internationale schaatsen. Op de Olympische Spelen behalen Nederlanders regelmatig medailles op het langebaanschaatsen. Schaatssteden zoals Heerenveen en Thialf zijn bekende namen in de wereld van de topsport.","Schaatsen is niet alleen voor topsporters. Miljoenen Nederlanders schaatsen recreatief. IJsbanen zijn in de wintermaanden populaire uitjes voor families en schoolklassen. Er zijn ook speciale schaatsroutes door het landschap, die worden bijgehouden door vrijwilligers zodra het ijs dik genoeg is."],"questions":[{"text":"Hoe lang is de Elfstedentocht?","type":"Detail","options":["Bijna honderd kilometer","Bijna driehonderd kilometer","Bijna vijftig kilometer","Bijna tweehonderd kilometer"],"correct":3,"highlight":"een tocht van bijna tweehonderd kilometer langs elf Friese steden","feedback":{"ok":"Goed! De Elfstedentocht is bijna tweehonderd kilometer.","nee":"Niet juist. Alinea 1: bijna tweehonderd kilometer."}},{"text":"Wanneer werd de laatste Elfstedentocht gereden?","type":"Detail","options":["In 2002","In 1985","In 1997","In 1990"],"correct":2,"highlight":"De laatste Elfstedentocht werd gereden in 1997","feedback":{"ok":"Correct! De laatste Elfstedentocht was in 1997.","nee":"Niet correct. Alinea 2: de laatste Elfstedentocht werd gereden in 1997."}},{"text":"Waarom is de Elfstedentocht de afgelopen decennia niet gereden?","type":"Inferentie","options":["Er zijn te weinig deelnemers.","De route is te gevaarlijk geworden.","Door klimaatverandering worden strenge winters steeds zeldzamer.","De organisatie is gestopt."],"correct":2,"highlight":"Door de klimaatverandering worden strenge winters steeds zeldzamer","feedback":{"ok":"Juist! Klimaatverandering maakt strenge winters zeldzamer.","nee":"Niet juist. Alinea 2: klimaatverandering maakt strenge winters zeldzamer."}},{"text":"Wat betekent 'recreatief' (alinea 4)?","type":"Woordbetekenis","options":["Voor competitie en prijzen","Voor geld en inkomen","Voor plezier en ontspanning, niet als topsport","Als onderdeel van je werk"],"correct":2,"highlight":"Miljoenen Nederlanders schaatsen recreatief","feedback":{"ok":"Goed! Recreatief = voor plezier en ontspanning.","nee":"Niet juist. Recreatief betekent voor plezier en ontspanning, niet als topsport."}},{"text":"Wat maakt schaatsen in Nederland bijzonder?","type":"Hoofdgedachte","options":["Het is de enige sport waarbij Nederlanders medailles winnen.","Het is alleen mogelijk in professionele ijshallen.","Het is een cultureel fenomeen dat veel verder gaat dan topsport.","Het is recent populair geworden door de media."],"correct":2,"highlight":"Schaatsen is in Nederland meer dan een sport — het is een cultureel fenomeen","feedback":{"ok":"Prima! Schaatsen is een cultureel fenomeen dat meer is dan topsport.","nee":"Niet correct. Alinea 1: schaatsen is een cultureel fenomeen dat verder gaat dan topsport."}}]},{"topic":"Immigratie","title":"Nieuwkomers in Nederland: inburgering en integratie","paragraphs":["Elk jaar komen er tienduizenden mensen naar Nederland om er te wonen en te werken. Ze komen uit allerlei landen: uit andere EU-landen voor werk, uit vluchtelingenlanden voor veiligheid, of als gezinsmigranten die zich bij familieleden voegen. Nederland heeft al eeuwenlang een traditie van opvang van vluchtelingen en arbeidsmigranten.","Nieuwkomers die van buiten de EU komen en langer dan vijf jaar in Nederland willen blijven, zijn verplicht in te burgeren. Inburgering betekent het leren van de Nederlandse taal en kennis opdoen over de Nederlandse samenleving. Hiervoor moeten ze een inburgeringsexamen afleggen dat bestaat uit meerdere onderdelen, waaronder taal en maatschappelijke oriëntatie.","Integratie gaat verder dan inburgeren. Het gaat om het vinden van werk, het opbouwen van sociale contacten en het deelnemen aan de samenleving. Onderzoek wijst uit dat integratie het best verloopt als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen. Sociale isolatie is een groot risico voor mensen die thuis blijven.","Het integratiedebat in Nederland is politiek gevoelig. Sommige partijen pleiten voor een strenger migratiebeleid, anderen benadrukken het belang van diversiteit voor de economie en de samenleving. Wetenschappers wijzen erop dat migranten economisch een positieve bijdrage leveren, maar dat de snelheid van integratie sterk afhangt van individuele omstandigheden en overheidsbeleid."],"questions":[{"text":"Wie zijn verplicht in te burgeren in Nederland?","type":"Detail","options":["Alle mensen die naar Nederland komen.","Alle EU-burgers die in Nederland werken.","Mensen van buiten de EU die langer dan vijf jaar willen blijven.","Alleen vluchtelingen."],"correct":2,"highlight":"Nieuwkomers die van buiten de EU komen en langer dan vijf jaar in Nederland willen blijven, zijn verplicht in te burgeren","feedback":{"ok":"Goed! Mensen van buiten de EU die langer dan vijf jaar willen blijven.","nee":"Niet juist. Alinea 2: mensen van buiten de EU die langer dan vijf jaar willen blijven."}},{"text":"Wat houdt inburgering in?","type":"Detail","options":["Alleen het vinden van werk.","Het leren van de taal en kennis opdoen over de Nederlandse samenleving.","Het aanvragen van een paspoort.","Het volgen van beroepsopleidingen."],"correct":1,"highlight":"het leren van de Nederlandse taal en kennis opdoen over de Nederlandse samenleving","feedback":{"ok":"Correct! Taal leren en kennis opdoen over de samenleving.","nee":"Niet correct. Alinea 2: taal leren en kennis opdoen over de Nederlandse samenleving."}},{"text":"Wanneer verloopt integratie het best?","type":"Inferentie","options":["Als nieuwkomers in eigen wijken wonen.","Als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen.","Als nieuwkomers een jaar thuisblijven.","Als nieuwkomers meteen staatsexamen doen."],"correct":1,"highlight":"integratie het best verloopt als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen","feedback":{"ok":"Juist! Snel toegang tot werk en taalonderwijs helpt integratie.","nee":"Niet juist. Alinea 3: integratie verloopt het best met snel toegang tot werk en taalonderwijs."}},{"text":"Wat betekent 'sociale isolatie' (alinea 3)?","type":"Woordbetekenis","options":["Te veel contacten hebben in de samenleving","Buiten de samenleving staan en weinig sociale contacten hebben","Een psychische aandoening veroorzaakt door stress","Het bewust kiezen voor een rustig leven"],"correct":1,"highlight":"Sociale isolatie is een groot risico voor mensen die thuis blijven","feedback":{"ok":"Goed! Sociale isolatie = buiten de samenleving staan met weinig contacten.","nee":"Niet juist. Sociale isolatie betekent buiten de samenleving staan en weinig sociale contacten hebben."}},{"text":"Wat concluderen wetenschappers over migranten?","type":"Detail","options":["Migranten kosten de samenleving alleen geld.","Migranten passen zich nooit aan aan de Nederlandse samenleving.","Migranten leveren economisch een positieve bijdrage.","Migranten willen niet integreren."],"correct":2,"highlight":"migranten economisch een positieve bijdrage leveren","feedback":{"ok":"Prima! Migranten leveren economisch een positieve bijdrage.","nee":"Niet correct. Alinea 4: migranten leveren economisch een positieve bijdrage."}}]},{"topic":"Natuur","title":"Bloembollenvelden: kleur in het polderlandschap","paragraphs":["In het voorjaar kleurt een groot deel van het Nederlandse landschap in felle tinten rood, geel, roze en paars. De bloembollenvelden van tulpen, narcissen en hyacinten zijn een van de meest herkenbare beelden van Nederland. De Bollenstreek, een gebied tussen Leiden en Haarlem, is het hart van de bollenteelt.","Nederland is de grootste exporteur van bloembollen ter wereld. Jaarlijks exporteert Nederland voor miljarden euro's aan bloembollen en snijbloemen naar meer dan honderd landen. De veiling in Aalsmeer, FloraHolland, is de grootste bloemenveilig ter wereld en verhandelt dagelijks miljoenen bloemen.","De bollenteelt heeft grote gevolgen voor het landschap, maar ook voor het milieu. Het gebruik van pesticiden en kunstmest heeft de biodiversiteit in de Bollenstreek aangetast. Grondwater raakt verontreinigd en insectenpopulaties nemen af. Steeds meer telers experimenteren met biologische teeltmethoden om deze schade te beperken.","Toeristen komen van heinde en ver om de bloembollenvelden te bewonderen. Keukenhof, een groot bloemenparkgoed in Lisse, ontvangt jaarlijks meer dan een miljoen bezoekers uit de hele wereld. Het park is slechts enkele weken per jaar open, maar trekt in die korte periode enorme drukte."],"questions":[{"text":"Waar ligt de Bollenstreek?","type":"Detail","options":["Tussen Amsterdam en Utrecht","Tussen Rotterdam en Den Haag","Tussen Leiden en Haarlem","Tussen Haarlem en Amsterdam"],"correct":2,"highlight":"De Bollenstreek, een gebied tussen Leiden en Haarlem","feedback":{"ok":"Goed! De Bollenstreek ligt tussen Leiden en Haarlem.","nee":"Niet juist. Alinea 1: tussen Leiden en Haarlem."}},{"text":"Hoeveel landen importeren Nederlandse bloembollen?","type":"Detail","options":["Meer dan vijftig landen","Meer dan tweehonderd landen","Meer dan honderd landen","Meer dan zeventig landen"],"correct":2,"highlight":"naar meer dan honderd landen","feedback":{"ok":"Correct! Meer dan honderd landen importeren Nederlandse bloembollen.","nee":"Niet correct. Alinea 2: naar meer dan honderd landen."}},{"text":"Wat is een negatief milieugevolg van de bollenteelt?","type":"Detail","options":["Overproductie van zuurstof door de bloemen.","Verontreiniging van grondwater en afname van insectenpopulaties.","Te veel bijen door de overvloed aan bloemen.","Verlies van landbouwgrond door de bollenteelt."],"correct":1,"highlight":"Grondwater raakt verontreinigd en insectenpopulaties nemen af","feedback":{"ok":"Juist! Grondwaterverontreiniging en afname van insectenpopulaties.","nee":"Niet juist. Alinea 3: grondwater raakt verontreinigd en insectenpopulaties nemen af."}},{"text":"Wat betekent 'verontreinigd' (alinea 3)?","type":"Woordbetekenis","options":["Opgedroogd en onbruikbaar","Vervuild met schadelijke stoffen","Overvol met water","Verwarmd door de zon"],"correct":1,"highlight":"Grondwater raakt verontreinigd","feedback":{"ok":"Goed! Verontreinigd = vervuild met schadelijke stoffen.","nee":"Niet juist. Verontreinigd betekent vervuild met schadelijke stoffen."}},{"text":"Hoe lang is Keukenhof per jaar open?","type":"Inferentie","options":["Het hele jaar","Een half jaar","Slechts enkele weken","Vier maanden"],"correct":2,"highlight":"Het park is slechts enkele weken per jaar open","feedback":{"ok":"Prima! Keukenhof is slechts enkele weken per jaar open.","nee":"Niet correct. Alinea 4: het park is slechts enkele weken per jaar open."}}]},{"topic":"Taal","title":"Dialect of standaardtaal: de strijd om de Nederlandse taal","paragraphs":["Nederland kent een rijke dialecttraditie. Van het Gronings in het noorden tot het Limburgs in het zuiden: elke regio heeft zijn eigen taalvarianten met unieke klanken, woorden en grammatica. Sommige dialecten, zoals het Zeeuws en het Twents, zijn zo anders dat sprekers van de standaardtaal ze amper begrijpen.","Het gebruik van dialect is de afgelopen eeuwen sterk afgenomen. Door de opkomst van nationale media, onderwijs in standaardnederlands en de toegenomen mobiliteit van mensen, spreken steeds minder Nederlanders nog dialect. Jongeren gebruiken dialect minder dan ouderen, en in steden verdwijnt het sneller dan op het platteland.","Toch is er ook hernieuwde interesse in dialect. Streektalen zoals het Fries, het Limburgs en het Nedersaksisch zijn officieel erkend als regionale talen in Nederland. Fries heeft zelfs een co-officiële status in de provincie Friesland: overheidsdocumenten worden er in zowel Nederlands als Fries gepubliceerd.","Linguïsten waarschuwen dat veel dialecten op de rand van uitsterven staan. Als de laatste sprekers overlijden zonder dat hun taal is gedocumenteerd, gaat een stuk cultureel erfgoed verloren. Er zijn projecten om dialecten op te nemen en vast te leggen voor toekomstige generaties, zodat het talig erfgoed bewaard blijft."],"questions":[{"text":"Welk dialect is zo anders dat standaardtaalsprekers het amper begrijpen?","type":"Detail","options":["Het Amsterdams en het Rotterdams","Het Haags en het Utrechts","Het Zeeuws en het Twents","Het Gronings en het Limburgs"],"correct":2,"highlight":"Sommige dialecten, zoals het Zeeuws en het Twents, zijn zo anders dat sprekers van de standaardtaal ze amper begrijpen","feedback":{"ok":"Goed! Het Zeeuws en het Twents zijn moeilijk begrijpbaar.","nee":"Niet juist. Alinea 1: het Zeeuws en het Twents zijn zo anders dat standaardtaalsprekers ze amper begrijpen."}},{"text":"Waarom neemt het gebruik van dialect af?","type":"Detail","options":["Omdat dialecten verboden zijn op scholen.","Omdat jongeren dialecten lelijker vinden.","Door nationale media, onderwijs en toegenomen mobiliteit.","Omdat standaardnederlands makkelijker te leren is."],"correct":2,"highlight":"door de opkomst van nationale media, onderwijs in standaardnederlands en de toegenomen mobiliteit van mensen","feedback":{"ok":"Correct! Nationale media, onderwijs en mobiliteit verklaren de afname.","nee":"Niet correct. Alinea 2: nationale media, onderwijs en toegenomen mobiliteit."}},{"text":"Welke bijzondere status heeft het Fries in Friesland?","type":"Detail","options":["Het is de enige officiële taal van Friesland.","Het is verboden in officiële communicatie.","Het heeft een co-officiële status naast het Nederlands.","Het wordt alleen op scholen onderwezen."],"correct":2,"highlight":"Fries heeft zelfs een co-officiële status in de provincie Friesland","feedback":{"ok":"Juist! Fries heeft een co-officiële status in Friesland.","nee":"Niet juist. Alinea 3: Fries heeft een co-officiële status in Friesland."}},{"text":"Wat betekent 'uitsterven' (alinea 4)?","type":"Woordbetekenis","options":["Steeds populairder worden","Volledig verdwijnen omdat er geen sprekers meer zijn","Verboden worden door de overheid","Veranderen in een andere taal"],"correct":1,"highlight":"veel dialecten op de rand van uitsterven staan","feedback":{"ok":"Goed! Uitsterven = volledig verdwijnen omdat er geen sprekers meer zijn.","nee":"Niet juist. Uitsterven betekent dat iets volledig verdwijnt omdat er geen dragers meer zijn."}},{"text":"Waarom worden dialecten opgenomen en vastgelegd?","type":"Inferentie","options":["Zodat ze op scholen onderwezen kunnen worden.","Zodat het talig erfgoed bewaard blijft voor toekomstige generaties.","Zodat wetenschappers betere woordenboeken kunnen maken.","Zodat dialectsprekers meer geld kunnen verdienen."],"correct":1,"highlight":"zodat het talig erfgoed bewaard blijft","feedback":{"ok":"Prima! Vastleggen zorgt dat het talig erfgoed bewaard blijft.","nee":"Niet correct. Alinea 4: zodat het talig erfgoed bewaard blijft voor toekomstige generaties."}}]},{"topic":"Steden","title":"Rotterdam: de stad die zichzelf opnieuw uitvond","paragraphs":["Rotterdam is de op een na grootste stad van Nederland en heeft de grootste haven van Europa. Op 14 mei 1940 werd het stadscentrum van Rotterdam vrijwel volledig verwoest door een bombardement van de Duitse luchtmacht. De stad moest na de Tweede Wereldoorlog van bijna niets opnieuw worden opgebouwd.","De wederopbouw van Rotterdam bood een unieke kans om een moderne stad te ontwerpen. Waar andere Nederlandse steden historische binnensteden bewaarden, kon Rotterdam experimenteren met nieuwe architectuur en stedenbouw. Dit leidde tot een skyline die in Nederland uniek is, met wolkenkrabbers, futuristische gebouwen en brede boulevards.","Rotterdam is een echte havenstad. De Rotterdamse haven, de Maasvlakte, strekt zich uit over tientallen kilometers en verwerkt jaarlijks honderden miljoenen tonnen goederen. Container- en bulkschepen uit de hele wereld lossen en laden hun goederen. De haven is een van de belangrijkste economische motoren van Nederland en Europa.","Ondanks zijn industriële imago heeft Rotterdam zich de afgelopen decennia ook cultureel ontwikkeld. Het Boijmans Van Beuningen museum, architectuurroutes en festivals als North Sea Jazz trekken bezoekers van over de hele wereld. De stad staat bekend om zijn multiculturele bevolking: meer dan de helft van de Rotterdammers heeft een niet-Nederlandse achtergrond."],"questions":[{"text":"Wanneer werd het centrum van Rotterdam verwoest?","type":"Detail","options":["Op 10 mei 1945","Op 14 mei 1940","Op 10 mei 1940","Op 14 mei 1945"],"correct":1,"highlight":"Op 14 mei 1940 werd het stadscentrum van Rotterdam vrijwel volledig verwoest","feedback":{"ok":"Goed! Op 14 mei 1940.","nee":"Niet juist. Alinea 1: op 14 mei 1940."}},{"text":"Wat maakte de wederopbouw van Rotterdam bijzonder?","type":"Detail","options":["Rotterdam koos voor herstel van de historische gebouwen.","Rotterdam mocht experimenteren met moderne architectuur en stedenbouw.","Rotterdam vroeg Belgische architecten om de stad te ontwerpen.","Rotterdam werd kleiner herbouwd dan voor de oorlog."],"correct":1,"highlight":"kon Rotterdam experimenteren met nieuwe architectuur en stedenbouw","feedback":{"ok":"Correct! Rotterdam kon experimenteren met nieuwe architectuur.","nee":"Niet correct. Alinea 2: Rotterdam kon experimenteren met nieuwe architectuur en stedenbouw."}},{"text":"Hoeveel goederen verwerkt de Rotterdamse haven per jaar?","type":"Detail","options":["Tientallen miljoenen tonnen","Honderden miljoenen tonnen","Miljoenen tonnen","Miljarden tonnen"],"correct":1,"highlight":"verwerkt jaarlijks honderden miljoenen tonnen goederen","feedback":{"ok":"Juist! Honderden miljoenen tonnen per jaar.","nee":"Niet juist. Alinea 3: honderden miljoenen tonnen goederen per jaar."}},{"text":"Wat betekent 'multicultureel' (alinea 4)?","type":"Woordbetekenis","options":["Bestaande uit mensen met veel verschillende culturele achtergronden","Een stad met veel verschillende restaurants","Een stad waar veel talen worden gesproken op scholen","Bestaande uit vooral internationale toeristen"],"correct":0,"highlight":"Rotterdam staat bekend om zijn multiculturele bevolking","feedback":{"ok":"Goed! Multicultureel = mensen met veel verschillende culturele achtergronden.","nee":"Niet juist. Multicultureel verwijst naar mensen met veel verschillende culturele achtergronden."}},{"text":"Welke culturele activiteit trekt bezoekers naar Rotterdam?","type":"Detail","options":["De Elfstedentocht","Het Amsterdam Dance Event","North Sea Jazz festival","Het Keukenhof"],"correct":2,"highlight":"festivals als North Sea Jazz trekken bezoekers van over de hele wereld","feedback":{"ok":"Prima! North Sea Jazz festival trekt bezoekers uit de hele wereld.","nee":"Niet correct. Alinea 4: North Sea Jazz festival trekt bezoekers."}}]}
];
